CREATE OR REPLACE FUNCTION "interno"."alarmas_a_la_vista_del_coordinador"("p_tipo" "text") RETURNS "uuid"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid := interno.prestadora_actual();
  v_llegaron uuid[];
  v_abiertas uuid[];
BEGIN
  IF v_prestadora IS NULL OR NOT interno.es_coordinador() THEN
    RETURN '{}';
  END IF;

  SELECT coalesce(array_agg(e.referencia_id), '{}') INTO v_llegaron
    FROM escalones_de_alarma_avisados e
   WHERE e.prestadora_id = v_prestadora
     AND e.tipo = p_tipo
     AND e.escalon = 'todos_los_coordinadores';

  IF p_tipo = 'alerta_temprana_guardia' THEN
    SELECT coalesce(array_agg(x.id), '{}') INTO v_abiertas FROM alertas_tempranas_guardia x
     WHERE x.id = ANY (v_llegaron) AND x.resuelto_at IS NULL;
  ELSIF p_tipo = 'incidente_relevo' THEN
    SELECT coalesce(array_agg(x.id), '{}') INTO v_abiertas FROM incidentes_relevo x
     WHERE x.id = ANY (v_llegaron) AND x.resuelto_at IS NULL;
  ELSIF p_tipo = 'incidente_turno_sin_cubrir' THEN
    SELECT coalesce(array_agg(x.id), '{}') INTO v_abiertas FROM incidentes_turno_sin_cubrir x
     WHERE x.id = ANY (v_llegaron) AND x.resuelto_at IS NULL;
  ELSIF p_tipo = 'emergencia_guardia' THEN
    SELECT coalesce(array_agg(x.id), '{}') INTO v_abiertas FROM emergencias_guardia x
     WHERE x.id = ANY (v_llegaron) AND x.atendida_at IS NULL;
  ELSIF p_tipo = 'guardia_sin_cerrar' THEN
    SELECT coalesce(array_agg(x.id), '{}') INTO v_abiertas FROM guardias x
     WHERE x.id = ANY (v_llegaron) AND x.estado = 'activa';
  ELSE
    v_abiertas := '{}';
  END IF;

  RETURN v_abiertas || interno.alarmas_que_tengo_tomadas(p_tipo);
END;
$$;


ALTER FUNCTION "interno"."alarmas_a_la_vista_del_coordinador"("p_tipo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."alarmas_que_tengo_tomadas"("p_tipo" "text") RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT coalesce(array_agg(a.referencia_id), '{}')
    FROM alarmas_tomadas a
   WHERE a.prestadora_id = interno.prestadora_actual()
     AND a.tipo = p_tipo
     AND a.tomada_por = auth.uid()
     AND a.soltada_at IS NULL
     AND a.vence_at > now();
$$;


ALTER FUNCTION "interno"."alarmas_que_tengo_tomadas"("p_tipo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."alcanza_el_archivo_del_paciente"("p_ruta" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT interno.es_superadmin()
      OR interno.es_admin_prestadora()
      OR coalesce(interno.coordinador_ve_al_paciente(interno.paciente_de_la_ruta(p_ruta)), false);
$$;


ALTER FUNCTION "interno"."alcanza_el_archivo_del_paciente"("p_ruta" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."alcanza_la_informacion_de_salud"("p_paciente" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT p_paciente IS NOT NULL
     AND (NOT interno.rige_la_restriccion_de_hce(interno.prestadora_actual())
          OR interno.atiende_al_paciente(p_paciente)
          OR (interno.es_admin_prestadora()
              AND EXISTS (SELECT 1 FROM pacientes p
                           WHERE p.id = p_paciente
                             AND p.prestadora_id = interno.prestadora_actual())))
$$;


ALTER FUNCTION "interno"."alcanza_la_informacion_de_salud"("p_paciente" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."anotar_cambio_de_fecha_de_ausencia"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
BEGIN
  IF NEW.fecha_fin IS DISTINCT FROM OLD.fecha_fin THEN
    INSERT INTO public.ausencias_cambios_de_fecha (prestadora_id, ausencia_id, fecha_anterior, fecha_nueva)
    VALUES (NEW.prestadora_id, NEW.id, OLD.fecha_fin, NEW.fecha_fin);
    NEW.pregunta_vuelta_at := NULL;
    NEW.pregunta_vuelta_veces := 0;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."anotar_cambio_de_fecha_de_ausencia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."anotar_cambio_de_la_restriccion_de_hce"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_antes boolean := CASE WHEN TG_OP = 'UPDATE' THEN OLD.restriccion_de_hce ELSE true END;
BEGIN
  IF v_antes IS NOT DISTINCT FROM NEW.restriccion_de_hce OR auth.uid() IS NULL THEN
    RETURN NULL;
  END IF;

  INSERT INTO registro_actividad
    (prestadora_id, usuario_id, accion, tabla_afectada, registro_id, campos_cambiados, detalle)
  VALUES
    (NEW.prestadora_id, auth.uid(), 'cambio_de_permisos_de_la_prestadora',
     TG_TABLE_NAME, NEW.prestadora_id, ARRAY['restriccion_de_hce'],
     jsonb_build_object('alcance_anterior', v_antes, 'alcance_nuevo', NEW.restriccion_de_hce));

  RETURN NULL;
END;
$$;


ALTER FUNCTION "interno"."anotar_cambio_de_la_restriccion_de_hce"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."anotar_desde_cuando_se_controla_en_el_turno"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT NEW.control_de_ubicacion_en_el_turno THEN
    NEW.control_de_ubicacion_en_el_turno_desde := NULL;
  ELSIF TG_OP = 'INSERT' OR NOT OLD.control_de_ubicacion_en_el_turno THEN
    NEW.control_de_ubicacion_en_el_turno_desde := now();
  ELSE
    NEW.control_de_ubicacion_en_el_turno_desde := OLD.control_de_ubicacion_en_el_turno_desde;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."anotar_desde_cuando_se_controla_en_el_turno"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."anotar_deuda_de_la_baja"("p_baja" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_baja bajas_de_servicio%ROWTYPE;
  v_servicio servicios%ROWTYPE;
  v_pagador uuid;
  v_contratante uuid;
  v_la_lleva_otro boolean;
  v_anotados integer;
BEGIN
  SELECT * INTO v_baja FROM bajas_de_servicio
   WHERE id = p_baja AND prestadora_id = interno.prestadora_actual();
  IF NOT FOUND THEN
    RETURN 0;
  END IF;

  IF EXISTS (SELECT 1 FROM configuracion_notificaciones
              WHERE prestadora_id = v_baja.prestadora_id
                AND evento = 'baja_servicio_con_deuda'
                AND activo = false) THEN
    RETURN 0;
  END IF;

  SELECT * INTO v_servicio FROM servicios WHERE id = v_baja.servicio_id;

  SELECT cc.pagador_persona_id, cc.contratante_persona_id INTO v_pagador, v_contratante
    FROM condiciones_comerciales_servicio cc
   WHERE cc.servicio_id = v_servicio.id AND cc.prestadora_id = v_baja.prestadora_id;

  SELECT coalesce((regla ->> 'sigue_la_cobranza')::boolean, true) = false INTO v_la_lleva_otro
    FROM configuracion_facturacion_clientes
   WHERE prestadora_id = v_baja.prestadora_id;

  INSERT INTO avisos_baja_servicio_con_deuda
    (prestadora_id, servicio_id, baja_id, cliente_id, responsable_de_pagos_persona_id,
     contratante_persona_id, importe, moneda, dias_de_atraso)
  SELECT v_baja.prestadora_id, v_servicio.id, v_baja.id, v_servicio.cliente_id,
         v_pagador, v_contratante,
         d.importe, d.moneda, d.dias_de_atraso
    FROM (
      SELECT e.saldo AS importe, e.moneda, e.dias_de_atraso
        FROM estado_de_cuenta_externo_vigente e
       WHERE coalesce(v_la_lleva_otro, false)
         AND e.prestadora_id = v_baja.prestadora_id
         AND e.cliente_id = v_servicio.cliente_id
      UNION ALL
      SELECT sum(s.saldo), s.moneda,
             coalesce(current_date - min(s.fecha_vencimiento) FILTER (WHERE s.fecha_vencimiento < current_date), 0)
        FROM saldos_cliente s
       WHERE NOT coalesce(v_la_lleva_otro, false)
         AND s.prestadora_id = v_baja.prestadora_id
         AND s.cliente_id = v_servicio.cliente_id
         AND s.saldo > 0
       GROUP BY s.moneda
    ) d
   WHERE d.importe > 0
  ON CONFLICT (baja_id, moneda) DO NOTHING;

  GET DIAGNOSTICS v_anotados = ROW_COUNT;
  RETURN v_anotados;
END;
$$;


ALTER FUNCTION "interno"."anotar_deuda_de_la_baja"("p_baja" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."anotar_lo_que_se_leyo"("p_tabla" "text", "p_pacientes" "uuid"[], "p_origen" "text") RETURNS "void"
    LANGUAGE "sql"
    SET "search_path" TO 'public', 'interno'
    AS $$
  INSERT INTO consultas_a_hce (paciente_id, categorias, origen)
  SELECT DISTINCT p, ARRAY[p_tabla], p_origen
    FROM unnest(coalesce(p_pacientes, '{}'::uuid[])) p
   WHERE p IS NOT NULL;
$$;


