CREATE OR REPLACE FUNCTION "interno"."anotar_version_clinica"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_fila      jsonb;
  v_anterior  jsonb;
  v_operacion text;
  v_version   integer;
  v_prest     uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_fila := to_jsonb(OLD);
    v_operacion := 'baja';
  ELSIF TG_OP = 'INSERT' THEN
    v_fila := to_jsonb(NEW);
    v_operacion := 'alta';
  ELSE
    v_fila := to_jsonb(NEW);
    v_anterior := to_jsonb(OLD);
    -- Una escritura que no cambia ningún dato y no trae nota no es una versión nueva.
    IF (v_fila - 'updated_at' - 'nota_aclaratoria') = (v_anterior - 'updated_at' - 'nota_aclaratoria')
       AND (v_fila ->> 'nota_aclaratoria') IS NULL THEN
      RETURN NULL;
    END IF;
    v_operacion := 'modificacion';
  END IF;

  v_prest := (v_fila ->> 'prestadora_id')::uuid;
  IF v_prest IS NULL THEN
    RAISE EXCEPTION 'Un registro clínico sin Prestadora no se puede versionar';
  END IF;

  SELECT COALESCE(MAX(version), 0) + 1 INTO v_version
    FROM versiones_registro_clinico
   WHERE tabla = TG_TABLE_NAME AND registro_id = (v_fila ->> 'id')::uuid;

  INSERT INTO versiones_registro_clinico
    (prestadora_id, paciente_id, tabla, registro_id, version, operacion, datos,
     nota_aclaratoria, autor_id, credencial_rol)
  VALUES
    (v_prest, (v_fila ->> 'paciente_id')::uuid, TG_TABLE_NAME, (v_fila ->> 'id')::uuid, v_version,
     v_operacion, v_fila, CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE v_fila ->> 'nota_aclaratoria' END,
     auth.uid(), COALESCE(auth.jwt() ->> 'role', session_user::text));

  RETURN NULL;
END;
$$;


ALTER FUNCTION "interno"."anotar_version_clinica"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."asignar_numero_de_cliente"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
BEGIN
  IF NEW.numero_cliente IS NOT NULL THEN
    RAISE EXCEPTION 'numero_de_cliente_no_se_elige';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('clientes:' || NEW.prestadora_id::text));

  SELECT COALESCE(max(numero_cliente), 0) + 1
    INTO NEW.numero_cliente
    FROM public.clientes
   WHERE prestadora_id = NEW.prestadora_id;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."asignar_numero_de_cliente"() OWNER TO "postgres";


COMMENT ON FUNCTION "interno"."asignar_numero_de_cliente"() IS 'El numero de cliente, uno mas que el mayor de esa Prestadora. No se reasigna porque ningún Cliente se borra de la tabla.';



CREATE OR REPLACE FUNCTION "interno"."asignar_numero_de_legajo"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
begin
  if new.numero_legajo is not null then
    raise exception 'numero_de_legajo_no_se_elige';
  end if;

  perform pg_advisory_xact_lock(hashtext('asistentes:' || new.prestadora_id::text));

  select coalesce(max(numero_legajo), 0) + 1
    into new.numero_legajo
    from public.asistentes
   where prestadora_id = new.prestadora_id;

  return new;
end;
$$;


ALTER FUNCTION "interno"."asignar_numero_de_legajo"() OWNER TO "postgres";


