CREATE OR REPLACE FUNCTION "interno"."consultas_a_hce_por_vencer"("p_prestadora" "uuid") RETURNS TABLE("anio" integer, "desde" timestamp with time zone, "hasta" timestamp with time zone, "se_borra_el" "date", "preaviso_el" "date", "notificacion_el" "date")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'interno'
    AS $$
  WITH regla AS (
    SELECT r.plazo_meses, r.dias_de_preaviso, r.dias_de_notificacion
      FROM reglas_de_conservacion r
      JOIN prestadoras p ON p.id = p_prestadora AND p.pais = r.jurisdiccion
     WHERE r.clase_de_registro = 'consultas_a_hce'
       AND r.al_vencer = 'borrar'
       AND r.tramo = 1
       AND r.vigencia_desde <= current_date
       AND (r.vigencia_hasta IS NULL OR r.vigencia_hasta >= current_date)
     ORDER BY r.vigencia_desde DESC
     LIMIT 1
  ), primero AS (
    SELECT extract(year FROM min(a.momento) AT TIME ZONE 'UTC')::integer AS anio
      FROM consultas_a_hce a
     WHERE a.prestadora_id = p_prestadora
  ), fecha AS (
    SELECT pr.anio,
           (make_date(pr.anio + 1, 1, 1) + make_interval(months => rg.plazo_meses))::date AS se_borra_el,
           rg.dias_de_preaviso, rg.dias_de_notificacion
      FROM primero pr, regla rg
     WHERE pr.anio IS NOT NULL
  )
  SELECT f.anio,
         make_timestamptz(f.anio, 1, 1, 0, 0, 0, 'UTC'),
         make_timestamptz(f.anio + 1, 1, 1, 0, 0, 0, 'UTC'),
         f.se_borra_el,
         f.se_borra_el - f.dias_de_preaviso,
         f.se_borra_el - f.dias_de_notificacion
    FROM fecha f;
$$;


ALTER FUNCTION "interno"."consultas_a_hce_por_vencer"("p_prestadora" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."conversacion_intermediacion_es_propia"("p_conversacion_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM conversaciones_intermediacion c
     WHERE c.id = p_conversacion_id
       -- Primero la Prestadora, que sale de la cuenta con la que se entró y de ningún otro lado.
       AND c.prestadora_id = interno.prestadora_actual()
       -- Y después una de las dos puntas. Quien no es ninguna de las dos no resuelve nada:
       -- comparar contra una ficha que no existe da desconocido, y desconocido no deja pasar.
       AND (
            c.cliente_id = interno.cliente_id_de_usuario(auth.uid())
         OR c.asistente_id = interno.asistente_de_la_sesion()
       )
  )
$$;


ALTER FUNCTION "interno"."conversacion_intermediacion_es_propia"("p_conversacion_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "interno"."conversacion_intermediacion_es_propia"("p_conversacion_id" "uuid") IS 'Si el hilo de Match es de quien esta consultando: de su Prestadora, y con el como una de las dos puntas. Lo consultan las politicas de conversaciones_match y de mensajes_match, y es el unico lugar donde esa pregunta esta escrita.';



CREATE OR REPLACE FUNCTION "interno"."coordina_al_paciente"("p_paciente" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT p_paciente IS NOT NULL
     AND auth.uid() IS NOT NULL
     AND EXISTS (
       SELECT 1
         FROM pacientes p
         JOIN servicios s ON s.prestadora_id = p.prestadora_id
                         AND s.cliente_id = p.cliente_id
        WHERE p.id = p_paciente
          AND p.prestadora_id = interno.prestadora_actual()
          AND s.estado = 'vigente'
          AND s.coordinador_id = ANY (interno.coordinadores_que_represento())
     );
$$;


