CREATE OR REPLACE FUNCTION "interno"."crear_y_cerrar_servicios_lo_hace_quien_puede"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_cambia_estado boolean := TG_OP = 'UPDATE' AND NEW.estado IS DISTINCT FROM OLD.estado;
BEGIN
  IF COALESCE(auth.jwt() ->> 'role', '') <> 'authenticated' THEN
    RETURN NEW;
  END IF;

  IF (TG_OP = 'INSERT' OR v_cambia_estado)
     AND NOT (interno.es_admin_prestadora()
              OR interno.es_superadmin()
              OR interno.tiene_permiso('gestionar_servicios')) THEN
    RAISE EXCEPTION 'crear_y_cerrar_servicios_lo_hace_quien_puede';
  END IF;

  -- Una persona cambia el estado sólo por las dos funciones, que dejan el registro.
  IF v_cambia_estado
     AND COALESCE(current_setting('careonys.cambio_de_estado_del_servicio', true), '') <> NEW.id::text THEN
    RAISE EXCEPTION 'el_estado_del_servicio_cambia_por_la_baja_o_la_reactivacion';
  END IF;

  IF v_cambia_estado AND NEW.estado = 'de_baja'
     AND interno.guardias_asignadas_del_servicio(NEW.id) > 0 THEN
    RAISE EXCEPTION 'el_servicio_tiene_guardias_asignadas';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."crear_y_cerrar_servicios_lo_hace_quien_puede"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."cumple_modulo_11"("p_numero" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select case
    when p_numero !~ '^[0-9]{11}$' then false
    else (
      with suma as (
        select sum(substr(p_numero, i, 1)::int * (array[5,4,3,2,7,6,5,4,3,2])[i]) as s
          from generate_series(1, 10) as i
      )
      select case 11 - (s % 11)
               when 11 then 0
               when 10 then null
               else 11 - (s % 11)
             end is not distinct from substr(p_numero, 11, 1)::int
        from suma
    )
  end
$_$;


ALTER FUNCTION "interno"."cumple_modulo_11"("p_numero" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."dia_en_que_termina_guardia"("p_fecha" "date", "p_hora_inicio" time without time zone, "p_hora_fin" time without time zone, "p_dias_hasta_el_fin" smallint DEFAULT NULL::smallint) RETURNS "date"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
           -- Duración escrita: manda, y es el caso de toda guardia cargada de acá en adelante.
           WHEN p_dias_hasta_el_fin IS NOT NULL THEN p_fecha + p_dias_hasta_el_fin
           WHEN p_hora_fin IS NULL OR p_hora_inicio IS NULL THEN p_fecha
           -- Sin duración escrita se cae en la regla vieja, que sólo sabe de la guardia de noche.
           WHEN p_hora_fin <= p_hora_inicio THEN p_fecha + 1
           ELSE p_fecha
         END;
$$;


ALTER FUNCTION "interno"."dia_en_que_termina_guardia"("p_fecha" "date", "p_hora_inicio" time without time zone, "p_hora_fin" time without time zone, "p_dias_hasta_el_fin" smallint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."documento_autorizacion_signos_vitales"("p_paciente" "uuid", "p_idioma" "text") RETURNS TABLE("titulo" "text", "texto" "text", "verificador" "text", "idioma" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  WITH datos AS (
    SELECT pa.prestadora_id, pr.pais, pr.nombre_fantasia,
           btrim(coalesce(pe.nombre, '') || ' ' || coalesce(pe.apellido, '')) AS paciente
      FROM pacientes pa
      JOIN prestadoras pr ON pr.id = pa.prestadora_id
      JOIN personas pe ON pe.id = pa.persona_id
     WHERE pa.id = p_paciente
  ),
  fabrica AS (
    SELECT t.titulo, t.cuerpo
      FROM textos_consentimiento t, datos d
     WHERE t.clave = 'autorizacion_signos_vitales'
       AND t.jurisdiccion = d.pais
       AND t.idioma = p_idioma
       AND NOT t.es_borrador
       AND t.vigente_hasta IS NULL
     ORDER BY t.version DESC
     LIMIT 1
  ),
  armado AS (
    SELECT f.titulo,
           replace(replace(coalesce(o.cuerpo, f.cuerpo), '{{prestadora}}', d.nombre_fantasia), '{{paciente}}', d.paciente) AS texto
      FROM datos d
      JOIN fabrica f ON true
      LEFT JOIN textos_autorizacion_signos_vitales o ON o.prestadora_id = d.prestadora_id AND o.idioma = p_idioma
  )
  SELECT a.titulo, a.texto, encode(sha256(convert_to(a.texto, 'UTF8')), 'hex'), p_idioma
    FROM armado a;
$$;


ALTER FUNCTION "interno"."documento_autorizacion_signos_vitales"("p_paciente" "uuid", "p_idioma" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."documentos_que_bloquean"("p_asistente_id" "uuid", "p_dia" "date", "p_paciente_id" "uuid" DEFAULT NULL::"uuid", "p_servicio_id" "uuid" DEFAULT NULL::"uuid") RETURNS "text"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_prestadora_id uuid;
  v_tipo_id       uuid;
  v_tipo          record;
  v_hasta         date;
  v_vencio        date;
  v_bloquean      text[] := ARRAY[]::text[];
BEGIN
  IF p_asistente_id IS NULL THEN
    RETURN v_bloquean;
  END IF;

  SELECT a.prestadora_id, a.tipo_asistente_id INTO v_prestadora_id, v_tipo_id
    FROM public.asistentes a
   WHERE a.id = p_asistente_id;

  IF COALESCE(auth.jwt() ->> 'role', '') NOT IN ('', 'service_role')
     AND v_prestadora_id IS DISTINCT FROM interno.prestadora_actual() THEN
    RAISE EXCEPTION 'El Asistente no pertenece a la Prestadora de quien pregunta'
      USING ERRCODE = '42501';
  END IF;

  IF v_tipo_id IS NULL THEN
    RETURN v_bloquean;
  END IF;

  FOR v_tipo IN
    SELECT t.id, t.nombre
      FROM public.tipos_documento_asistente t
      JOIN public.tipos_documento_por_tipo_asistente r ON r.tipo_documento_id = t.id
     WHERE t.prestadora_id = v_prestadora_id
       AND t.activo
       AND t.impide_trabajar
       AND r.tipo_asistente_id = v_tipo_id
     ORDER BY t.nombre
  LOOP
    CONTINUE WHEN EXISTS (
      SELECT 1 FROM public.documentos_asistente d
       WHERE d.asistente_id = p_asistente_id
         AND d.tipo_documento_id = v_tipo.id
         AND d.estado = 'aprobado'
         AND (d.fecha_vencimiento IS NULL OR d.fecha_vencimiento >= p_dia));

    v_hasta := interno.gracia_hasta(p_asistente_id, v_tipo.id, p_dia);

    IF v_hasta IS NOT NULL AND v_hasta >= p_dia THEN
      SELECT max(d.fecha_vencimiento) INTO v_vencio
        FROM public.documentos_asistente d
       WHERE d.asistente_id = p_asistente_id
         AND d.tipo_documento_id = v_tipo.id
         AND d.estado = 'aprobado'
         AND d.fecha_vencimiento < p_dia;

      CONTINUE WHEN EXISTS (
        SELECT 1 FROM public.guardias g
         WHERE g.asistente_id = p_asistente_id
           AND g.fecha <= v_vencio
           AND g.estado <> 'cancelada'
           AND (g.paciente_id = p_paciente_id OR g.servicio_id = p_servicio_id))
      OR EXISTS (
        SELECT 1 FROM public.series_guardias s
         WHERE s.asistente_id = p_asistente_id
           AND s.estado = 'activa'
           AND s.paciente_id = p_paciente_id);
    END IF;

    v_bloquean := v_bloquean || v_tipo.nombre;
  END LOOP;

  RETURN v_bloquean;
END;
$$;


ALTER FUNCTION "interno"."documentos_que_bloquean"("p_asistente_id" "uuid", "p_dia" "date", "p_paciente_id" "uuid", "p_servicio_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."el_asistente_marca_solo_su_guardia"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_suyas constant text[] := ARRAY[
    'salida_checkin_at', 'salida_lat', 'salida_lng', 'medio_transporte',
    'checkin_at', 'checkin_lat', 'checkin_lng',
    'checkout_at', 'checkout_lat', 'checkout_lng',
    'estado',
    'ubicacion_actual_lat', 'ubicacion_actual_lng', 'ubicacion_actual_at',
    'push_llegada_enviado_at', 'push_reporte_enviado_at'
  ];
BEGIN
  IF current_user <> 'authenticated' THEN
    RETURN NEW;
  END IF;
  IF interno.es_personal_de_la_prestadora() THEN
    RETURN NEW;
  END IF;

  IF (to_jsonb(NEW) - v_suyas) IS DISTINCT FROM (to_jsonb(OLD) - v_suyas) THEN
    RAISE EXCEPTION 'la_persona_cambia_solo_lo_suyo' USING ERRCODE = '42501';
  END IF;

  -- La salida, la llegada y el cierre: se marcan una vez, con todo lo suyo, y no se reescriben.
  IF (NEW.salida_checkin_at, NEW.salida_lat, NEW.salida_lng, NEW.medio_transporte)
       IS DISTINCT FROM (OLD.salida_checkin_at, OLD.salida_lat, OLD.salida_lng, OLD.medio_transporte)
     AND (OLD.salida_checkin_at IS NOT NULL OR NEW.salida_checkin_at IS NULL) THEN
    RAISE EXCEPTION 'la_persona_cambia_solo_lo_suyo' USING ERRCODE = '42501';
  END IF;
  IF (NEW.checkin_at, NEW.checkin_lat, NEW.checkin_lng)
       IS DISTINCT FROM (OLD.checkin_at, OLD.checkin_lat, OLD.checkin_lng)
     AND (OLD.checkin_at IS NOT NULL OR NEW.checkin_at IS NULL OR NEW.estado IS DISTINCT FROM 'activa') THEN
    RAISE EXCEPTION 'la_persona_cambia_solo_lo_suyo' USING ERRCODE = '42501';
  END IF;
  IF (NEW.checkout_at, NEW.checkout_lat, NEW.checkout_lng)
       IS DISTINCT FROM (OLD.checkout_at, OLD.checkout_lat, OLD.checkout_lng)
     AND (OLD.checkout_at IS NOT NULL OR NEW.checkout_at IS NULL OR NEW.estado IS DISTINCT FROM 'completada') THEN
    RAISE EXCEPTION 'la_persona_cambia_solo_lo_suyo' USING ERRCODE = '42501';
  END IF;

  -- El estado: a empezada al llegar, desde una guardia que todavía no empezó y no se canceló; a
  -- terminada al cerrar, desde una empezada. Ningún otro cambio es del Asistente.
  IF NEW.estado IS DISTINCT FROM OLD.estado
     AND NOT (
       (NEW.estado = 'activa' AND OLD.estado IN ('programada', 'ausente', 'pausada')
          AND OLD.checkin_at IS NULL AND NEW.checkin_at IS NOT NULL)
       OR
       (NEW.estado = 'completada' AND OLD.estado = 'activa'
          AND OLD.checkout_at IS NULL AND NEW.checkout_at IS NOT NULL)
     ) THEN
    RAISE EXCEPTION 'la_persona_cambia_solo_lo_suyo' USING ERRCODE = '42501';
  END IF;

  -- Los avisos ya mandados no se desmarcan: desmarcarlos los volvería a mandar.
  IF (OLD.push_llegada_enviado_at IS NOT NULL AND NEW.push_llegada_enviado_at IS DISTINCT FROM OLD.push_llegada_enviado_at)
     OR (OLD.push_reporte_enviado_at IS NOT NULL AND NEW.push_reporte_enviado_at IS DISTINCT FROM OLD.push_reporte_enviado_at) THEN
    RAISE EXCEPTION 'la_persona_cambia_solo_lo_suyo' USING ERRCODE = '42501';
  END IF;

  -- La hora de cada marca es la de la base, no la que mande el teléfono.
  IF NEW.salida_checkin_at IS DISTINCT FROM OLD.salida_checkin_at THEN NEW.salida_checkin_at := now(); END IF;
  IF NEW.checkin_at IS DISTINCT FROM OLD.checkin_at THEN NEW.checkin_at := now(); END IF;
  IF NEW.checkout_at IS DISTINCT FROM OLD.checkout_at THEN NEW.checkout_at := now(); END IF;
  IF NEW.ubicacion_actual_at IS NOT NULL AND NEW.ubicacion_actual_at IS DISTINCT FROM OLD.ubicacion_actual_at THEN
    NEW.ubicacion_actual_at := now();
  END IF;
  IF NEW.push_llegada_enviado_at IS DISTINCT FROM OLD.push_llegada_enviado_at THEN NEW.push_llegada_enviado_at := now(); END IF;
  IF NEW.push_reporte_enviado_at IS DISTINCT FROM OLD.push_reporte_enviado_at THEN NEW.push_reporte_enviado_at := now(); END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."el_asistente_marca_solo_su_guardia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."el_contratante_lo_fija_la_administracion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
BEGIN
  IF NEW.cliente_id IS DISTINCT FROM OLD.cliente_id
     AND COALESCE(auth.jwt() ->> 'role', '') = 'authenticated'
     AND NOT (interno.es_admin_prestadora() OR interno.es_superadmin()) THEN
    RAISE EXCEPTION 'el_contratante_lo_fija_la_administracion';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."el_contratante_lo_fija_la_administracion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."el_coordinador_del_servicio_lo_asigna_la_administracion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.coordinador_id IS NOT DISTINCT FROM OLD.coordinador_id THEN
    NEW.coordinador_asignado_por := OLD.coordinador_asignado_por;
    NEW.coordinador_asignado_en := OLD.coordinador_asignado_en;
    RETURN NEW;
  END IF;

  IF NEW.coordinador_id IS NULL THEN
    IF TG_OP = 'UPDATE' THEN
      RAISE EXCEPTION 'el_servicio_no_se_queda_sin_coordinador';
    END IF;
    NEW.coordinador_asignado_por := NULL;
    NEW.coordinador_asignado_en := NULL;
    RETURN NEW;
  END IF;

  -- Una persona con sesión sólo asigna si administra la Prestadora. Lo que corre sin persona —el
  -- trabajo de la Prestadora, la carga de datos inventados— no pasa por esta pregunta.
  IF COALESCE(auth.jwt() ->> 'role', '') = 'authenticated'
     AND NOT (interno.es_admin_prestadora() OR interno.es_superadmin()) THEN
    RAISE EXCEPTION 'el_coordinador_lo_asigna_la_administracion';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM usuarios u
     WHERE u.id = NEW.coordinador_id
       AND u.prestadora_id = NEW.prestadora_id
       AND u.rol = 'coordinador'
       AND u.desactivada_en IS NULL
  ) THEN
    RAISE EXCEPTION 'el_asignado_no_coordina_en_la_prestadora';
  END IF;

  NEW.coordinador_asignado_por := CASE WHEN auth.uid() IS NULL THEN NEW.coordinador_asignado_por
                                       ELSE auth.uid() END;
  NEW.coordinador_asignado_en := now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."el_coordinador_del_servicio_lo_asigna_la_administracion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."el_documento_del_asistente_es_valido"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
declare
  v record;
begin
  if new.genero is null or btrim(new.genero) = '' then
    raise exception 'falta_el_genero';
  end if;
  select * into v
    from interno.identidad_validada(new.prestadora_id, 'fisica', new.documento_tipo,
                                    new.documento_numero, new.documento_pais, new.dni, new.genero);
  new.documento_numero := v.numero;
  new.documento_pais := v.pais;
  new.dni := v.dni;
  new.genero := v.genero;
  return new;
end;
$$;


ALTER FUNCTION "interno"."el_documento_del_asistente_es_valido"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."el_documento_es_valido"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
declare
  v record;
begin
  select * into v
    from interno.identidad_validada(new.prestadora_id, new.clase, new.documento_tipo,
                                    new.documento_numero, new.documento_pais, new.dni, new.genero);
  new.documento_numero := v.numero;
  new.documento_pais := v.pais;
  new.dni := v.dni;
  new.genero := v.genero;
  return new;
end;
$$;


