CREATE OR REPLACE FUNCTION "interno"."la_clave_de_la_administracion_la_cambia_celtatech"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
declare
  v_permiso uuid;
begin
  if not interno.es_cuenta_de_administracion(new.id) then
    return new;
  end if;

  update interno.cambios_de_clave_autorizados
     set usado_en = now()
   where id = (
     select id from interno.cambios_de_clave_autorizados
      where usuario_id = new.id and usado_en is null and anulado_en is null and expira_en > now()
      order by created_at desc
      limit 1
      for update
   )
  returning id into v_permiso;

  if v_permiso is null then
    raise exception 'la contraseña de una cuenta de administración la cambia CeltaTech'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "interno"."la_clave_de_la_administracion_la_cambia_celtatech"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."la_direccion_de_la_prestadora_es_suya"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $_$
DECLARE nueva text;
BEGIN
  nueva := NULLIF(lower(btrim(COALESCE(NEW.dominio, ''))), '');

  IF TG_OP = 'UPDATE'
     AND OLD.dominio IS NOT NULL
     AND nueva IS DISTINCT FROM lower(btrim(OLD.dominio)) THEN
    RAISE EXCEPTION 'la_direccion_de_la_prestadora_no_cambia';
  END IF;

  NEW.dominio := nueva;

  IF nueva IS NULL THEN
    RETURN NEW;
  END IF;

  -- Letras sin acento, números, guiones y puntos, y ni un guión ni un punto en los extremos.
  IF nueva !~ '^[a-z0-9]([a-z0-9.-]*[a-z0-9])?$' THEN
    RAISE EXCEPTION 'la_direccion_de_la_prestadora_no_tiene_forma';
  END IF;

  RETURN NEW;
END;
$_$;


ALTER FUNCTION "interno"."la_direccion_de_la_prestadora_es_suya"() OWNER TO "postgres";


COMMENT ON FUNCTION "interno"."la_direccion_de_la_prestadora_es_suya"() IS 'El código de la Prestadora: en minúsculas, con forma válida, y una vez puesto no cambia.';



CREATE OR REPLACE FUNCTION "interno"."la_especialidad_es_de_su_tipo"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
begin
  if tg_table_name = 'especialidades' then
    if not exists (
      select 1 from public.tipos_asistente t
       where t.id = new.tipo_asistente_id
         and (t.prestadora_id is null or t.prestadora_id = new.prestadora_id)
    ) then
      raise exception 'El tipo de Asistente no existe o no es de esta Prestadora.' using errcode = 'P0001';
    end if;
  else
    if not exists (
      select 1
        from public.asistentes a
        join public.especialidades e on e.id = new.especialidad_id
       where a.id = new.asistente_id
         and a.tipo_asistente_id = e.tipo_asistente_id
    ) then
      raise exception 'Esa Especialidad no es del tipo de este Asistente.' using errcode = 'P0001';
    end if;
  end if;
  return new;
end;
$$;


