    AS $$
  SELECT COALESCE(
    NULLIF(
      ARRAY(
        SELECT pm.modalidad
          FROM public.prestadora_modalidades pm
         WHERE pm.prestadora_id = p_prestadora_id
           AND pm.activa
           AND pm.modalidad IN ('directa', 'intermediacion')
         ORDER BY pm.modalidad
      ),
      ARRAY[]::text[]
    ),
    ARRAY['directa']::text[]
  );
$$;


