CREATE OR REPLACE FUNCTION "interno"."numero_comparable"("p_telefono" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  SELECT CASE
           WHEN regexp_replace(coalesce(p_telefono, ''), '[^0-9]', '', 'g') = '' THEN NULL
           ELSE md5(regexp_replace(p_telefono, '[^0-9]', '', 'g'))
         END;
$$;


