COMMENT ON FUNCTION "interno"."puede_habilitar"("p_rol_de_quien" "text", "p_rol_del_destinatario" "text") IS 'Se habilita hacia abajo, y nunca a uno mismo ni a su propio escalón. Un rol que no se entiende —de cualquiera de los dos lados— no habilita y no es habilitado. Es la gemela de puedeHabilitar() del motor.';



CREATE OR REPLACE FUNCTION "interno"."quien_gestiona_al_apoderado"("p_cliente" "uuid", "p_usuario" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid := interno.prestadora_actual();
BEGIN
  IF v_prestadora IS NOT NULL THEN
    IF auth.jwt() ->> 'role' = 'trabajo_sin_persona' THEN
      IF p_usuario IS NOT NULL AND EXISTS (
        SELECT 1 FROM clientes c
         WHERE c.id = p_cliente AND c.prestadora_id = v_prestadora AND c.usuario_id = p_usuario
      ) THEN
        RETURN p_usuario;
      END IF;
    ELSIF interno.es_personal_de_la_prestadora()
      AND interno.tiene_permiso('registrar_consentimiento_pagador')
      AND EXISTS (SELECT 1 FROM clientes c WHERE c.id = p_cliente AND c.prestadora_id = v_prestadora) THEN
      RETURN auth.uid();
    END IF;
  END IF;
  RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
END;
$$;


