CREATE OR REPLACE FUNCTION "interno"."verificar_cadena_de_consultas"("p_prestadora" "uuid") RETURNS TABLE("intacta" boolean, "renglones" bigint, "rota_en_numero" bigint, "rota_en_id" "uuid", "motivo" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  r           consultas_a_hce;
  v_corte     record;
  v_esperado  bigint;
  v_anterior  bytea;
  v_cuantos   bigint := 0;
BEGIN
  SELECT c.hasta_numero, c.ultimo_resumen INTO v_corte
    FROM cortes_de_consultas_a_hce c
   WHERE c.prestadora_id = p_prestadora
   ORDER BY c.hasta_numero DESC
   LIMIT 1;
  v_esperado := COALESCE(v_corte.hasta_numero, 0) + 1;
  v_anterior := v_corte.ultimo_resumen;

  FOR r IN
    SELECT * FROM consultas_a_hce a
     WHERE a.prestadora_id = p_prestadora
     ORDER BY a.numero
  LOOP
    IF r.numero <> v_esperado THEN
      RETURN QUERY SELECT false, v_cuantos, r.numero, r.id, 'falta_un_renglon'::text;
      RETURN;
    END IF;
    IF r.resumen_anterior IS DISTINCT FROM v_anterior THEN
      RETURN QUERY SELECT false, v_cuantos, r.numero, r.id, 'no_sigue_al_anterior'::text;
      RETURN;
    END IF;
    IF r.resumen IS DISTINCT FROM interno.resumen_de_la_consulta(r) THEN
      RETURN QUERY SELECT false, v_cuantos, r.numero, r.id, 'el_renglon_fue_alterado'::text;
      RETURN;
    END IF;
    v_anterior := r.resumen;
    v_esperado := v_esperado + 1;
    v_cuantos := v_cuantos + 1;
  END LOOP;

  RETURN QUERY SELECT true, v_cuantos, NULL::bigint, NULL::uuid, NULL::text;
END;
$$;


ALTER FUNCTION "interno"."verificar_cadena_de_consultas"("p_prestadora" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."versionar_tabla_clinica"("p_tabla" "regclass") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $_$
DECLARE
  v_nombre text;
BEGIN
  SELECT c.relname INTO v_nombre
    FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
   WHERE c.oid = p_tabla AND n.nspname = 'public';
  IF v_nombre IS NULL THEN
    RAISE EXCEPTION 'Sólo se versionan tablas del esquema public: %', p_tabla;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                  WHERE table_schema = 'public' AND table_name = v_nombre
                    AND column_name = 'id' AND data_type = 'uuid')
     OR NOT EXISTS (SELECT 1 FROM information_schema.columns
                  WHERE table_schema = 'public' AND table_name = v_nombre
                    AND column_name = 'prestadora_id' AND data_type = 'uuid') THEN
    RAISE EXCEPTION 'La tabla % necesita id uuid y prestadora_id uuid para versionarse', v_nombre;
  END IF;

  EXECUTE format('ALTER TABLE %s ADD COLUMN IF NOT EXISTS nota_aclaratoria text', p_tabla);

  -- Lo que ya estaba escrito entra como primera versión. Lo que se pisó antes de hoy no se
  -- recupera: el momento es el de la última escritura conocida y el autor queda sin saberse.
  EXECUTE format($f$
    INSERT INTO versiones_registro_clinico
      (prestadora_id, paciente_id, tabla, registro_id, version, operacion, datos,
       nota_aclaratoria, autor_id, credencial_rol, momento)
    SELECT (to_jsonb(t) ->> 'prestadora_id')::uuid, (to_jsonb(t) ->> 'paciente_id')::uuid,
           %L, t.id, 1, 'anterior_al_historial', to_jsonb(t), NULL, NULL, session_user::text,
           COALESCE((to_jsonb(t) ->> 'updated_at')::timestamptz,
                    (to_jsonb(t) ->> 'created_at')::timestamptz, now())
      FROM %s t
     WHERE NOT EXISTS (SELECT 1 FROM versiones_registro_clinico v
                        WHERE v.tabla = %L AND v.registro_id = t.id)
  $f$, v_nombre, p_tabla, v_nombre);

  EXECUTE format('DROP TRIGGER IF EXISTS trg_la_nota_es_de_una_version ON %s', p_tabla);
  EXECUTE format('CREATE TRIGGER trg_la_nota_es_de_una_version BEFORE UPDATE ON %s
                  FOR EACH ROW EXECUTE FUNCTION interno.la_nota_aclaratoria_es_de_una_version()', p_tabla);

  EXECUTE format('DROP TRIGGER IF EXISTS trg_versiones_del_registro_clinico ON %s', p_tabla);
  EXECUTE format('CREATE TRIGGER trg_versiones_del_registro_clinico AFTER INSERT OR UPDATE OR DELETE ON %s
                  FOR EACH ROW EXECUTE FUNCTION interno.anotar_version_clinica()', p_tabla);
END;
$_$;


ALTER FUNCTION "interno"."versionar_tabla_clinica"("p_tabla" "regclass") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aceptar_asignacion"("p_asignacion_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid := interno.prestadora_actual();
  v_asistente  uuid := interno.asistente_de_la_sesion();
  v_asignacion public.asignaciones_de_turno;
  v_tomadas    integer;
BEGIN
  IF v_prestadora IS NULL OR v_asistente IS NULL THEN
    RAISE EXCEPTION 'asignacion_no_encontrada';
  END IF;

  SELECT * INTO v_asignacion
    FROM asignaciones_de_turno
   WHERE id = p_asignacion_id
     AND prestadora_id = v_prestadora
     AND asistente_id = v_asistente
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'asignacion_no_encontrada';
  END IF;

  IF v_asignacion.estado <> 'sin_responder' THEN
    RAISE EXCEPTION 'asignacion_ya_respondida';
  END IF;

  IF v_asignacion.guardia_id IS NOT NULL THEN
    UPDATE guardias
       SET asistente_id = v_asistente
     WHERE id = v_asignacion.guardia_id
       AND prestadora_id = v_prestadora
       AND estado = 'programada'
       AND asistente_id IS NULL;

    GET DIAGNOSTICS v_tomadas = ROW_COUNT;
    IF v_tomadas = 0 THEN
      RAISE EXCEPTION 'guardia_ya_cubierta';
    END IF;

  ELSIF v_asignacion.serie_id IS NOT NULL THEN
    UPDATE series_guardias
       SET asistente_id = v_asistente
     WHERE id = v_asignacion.serie_id
       AND prestadora_id = v_prestadora
       AND estado = 'activa'
       AND asistente_id IS NULL;

    GET DIAGNOSTICS v_tomadas = ROW_COUNT;
    IF v_tomadas = 0 THEN
      RAISE EXCEPTION 'guardia_ya_cubierta';
    END IF;

    -- Los turnos que vienen pasan a ser suyos: los que no tienen a nadie y los que seguía haciendo
    -- quien tenía el turno fijo antes. Los que esperan la respuesta de otro por ese día quedan como
    -- están. Ya contestó que sí: no le llega un aviso por cada día.
    UPDATE guardias g
       SET asistente_id = v_asistente,
           push_asignacion_enviado_at = now()
     WHERE g.serie_id = v_asignacion.serie_id
       AND g.prestadora_id = v_prestadora
       AND g.estado = 'programada'
       AND (g.asistente_id IS NULL OR g.asistente_id = v_asignacion.asistente_anterior_id)
       AND g.fecha >= CURRENT_DATE
       AND NOT EXISTS (
         SELECT 1 FROM asignaciones_de_turno o
          WHERE o.guardia_id = g.id
            AND o.estado = 'sin_responder'
       );

  ELSE
    UPDATE coberturas_de_ausencia
       SET aceptada_at = now()
     WHERE ausencia_id = v_asignacion.ausencia_id
       AND prestadora_id = v_prestadora
       AND asistente_sustituto_id = v_asistente
       AND aceptada_at IS NULL
       AND objetada_at IS NULL;
  END IF;

  UPDATE asignaciones_de_turno
     SET estado = 'aceptada'
   WHERE id = v_asignacion.id;

  RETURN v_asignacion.guardia_id;
END;
$$;


ALTER FUNCTION "public"."aceptar_asignacion"("p_asignacion_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."activar_la_cuenta"("p_codigo" "text", "p_clave" "text", "p_usuario" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid;
  v_usuario uuid;
  v_rol text;
  v_nombre text;
BEGIN
  IF auth.jwt() ->> 'role' IS DISTINCT FROM 'trabajo_sin_persona' THEN RETURN NULL; END IF;
  v_prestadora := interno.prestadora_actual();
  IF v_prestadora IS NULL OR coalesce(p_codigo, '') = '' OR coalesce(p_clave, '') = '' THEN
    RETURN NULL;
  END IF;

  UPDATE tokens_activacion_cuenta t SET usado_en = now()
    FROM usuarios u
   WHERE t.token = encode(extensions.digest(p_codigo, 'sha256'), 'hex')
     AND t.usado_en IS NULL AND t.expira_en > now()
     AND u.id = t.usuario_id AND u.prestadora_id = v_prestadora
     AND u.rol IN ('coordinador', 'asistente', 'cliente')
  RETURNING t.usuario_id, u.rol INTO v_usuario, v_rol;

  IF v_usuario IS NULL THEN RETURN NULL; END IF;

  -- La coordinación ya tiene el suyo. Asistentes y Clientes lo eligen ahora.
  IF v_rol IN ('asistente', 'cliente') THEN
    v_nombre := lower(btrim(coalesce(p_usuario, ''), E' \t\r\n'));
    IF v_nombre = '' THEN RAISE EXCEPTION 'faltan_datos'; END IF;
    IF NOT interno.usuario_elegido_bien_escrito(v_nombre) THEN RAISE EXCEPTION 'usuario_mal_escrito'; END IF;
    IF EXISTS (SELECT 1 FROM usuarios WHERE lower(nombre_de_usuario) = v_nombre AND id <> v_usuario
                  AND desactivada_en IS NULL) THEN
      RAISE EXCEPTION 'usuario_en_uso';
    END IF;
    BEGIN
      UPDATE usuarios SET nombre_de_usuario = v_nombre WHERE id = v_usuario;
    EXCEPTION WHEN unique_violation THEN
      RAISE EXCEPTION 'usuario_en_uso';
    END;
  END IF;

  UPDATE auth.users
     SET encrypted_password = extensions.crypt(p_clave, extensions.gen_salt('bf', 10)),
         updated_at = now()
   WHERE id = v_usuario;
  IF NOT FOUND THEN RAISE EXCEPTION 'activar_la_cuenta: la cuenta no tiene ingreso'; END IF;

  RETURN v_usuario;
END;
$$;


ALTER FUNCTION "public"."activar_la_cuenta"("p_codigo" "text", "p_clave" "text", "p_usuario" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agregar_informacion_de_salud"("p_tabla" "text", "p_origen" "text", "p_fila" "jsonb", "p_columnas_devueltas" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $_$
DECLARE
  v_antes     text := coalesce(current_setting('careonys.lectura_de_salud', true), '');
  v_cols      text[];
  v_lista     text;
  v_sql       text;
  v_resultado jsonb;
  v_pacientes uuid[];
BEGIN
  PERFORM interno.pedido_de_salud_valido(p_tabla, p_origen);
  IF p_fila IS NULL OR jsonb_typeof(p_fila) <> 'object' THEN
    RAISE EXCEPTION 'pedido_invalido' USING ERRCODE = '22023';
  END IF;
  v_cols := ARRAY(SELECT interno.columna_del_pedido(p_tabla, k) FROM jsonb_object_keys(p_fila) k);
  IF cardinality(v_cols) = 0 THEN
    RAISE EXCEPTION 'pedido_invalido' USING ERRCODE = '22023';
  END IF;
  SELECT string_agg(format('%I', c), ', ') INTO v_lista FROM unnest(v_cols) c;

  -- Sólo las columnas que llegaron: las demás toman su valor de fábrica.
  v_sql := format(
    'WITH i AS (
       INSERT INTO public.%I (%s) SELECT %s FROM jsonb_populate_record(NULL::public.%I, $1)
       RETURNING *),
     f AS (SELECT %s AS fila, %s AS pacientes FROM i t)
     SELECT coalesce(jsonb_agg(f.fila), ''[]''::jsonb),
            (SELECT array_agg(DISTINCT p) FROM f, unnest(f.pacientes) p WHERE p IS NOT NULL)
       FROM f',
    p_tabla, v_lista, v_lista, p_tabla,
    CASE WHEN p_columnas_devueltas IS NULL THEN 'jsonb_build_object(''id'', t.id)'
         ELSE interno.fila_del_pedido(p_tabla, p_columnas_devueltas) END,
    interno.pacientes_de_la_fila(p_tabla));

  PERFORM set_config('careonys.lectura_de_salud', 'anotada', true);
  EXECUTE v_sql INTO v_resultado, v_pacientes USING p_fila;
  PERFORM set_config('careonys.lectura_de_salud', v_antes, true);

  PERFORM interno.anotar_lo_que_se_leyo(p_tabla, v_pacientes, p_origen);
  RETURN v_resultado;
END;
$_$;


ALTER FUNCTION "public"."agregar_informacion_de_salud"("p_tabla" "text", "p_origen" "text", "p_fila" "jsonb", "p_columnas_devueltas" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."alcanza_al_asistente_la_sesion"("p_asistente" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM asistentes a
    WHERE a.id = p_asistente
      AND a.prestadora_id = interno.prestadora_actual()
      AND (interno.es_admin_prestadora() OR interno.coordinador_alcanza_asistente(a.id))
  );
$$;


ALTER FUNCTION "public"."alcanza_al_asistente_la_sesion"("p_asistente" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."alcanza_la_informacion_de_salud_la_sesion"("p_paciente" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT COALESCE(
    interno.usuario_de_la_sesion() IS NOT NULL
    AND EXISTS (SELECT 1 FROM pacientes p
                 WHERE p.id = p_paciente
                   AND p.prestadora_id = interno.prestadora_actual())
    AND interno.alcanza_la_informacion_de_salud(p_paciente),
    false);
$$;


ALTER FUNCTION "public"."alcanza_la_informacion_de_salud_la_sesion"("p_paciente" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."anotar_aviso_de_borrado_de_consultas_a_hce"("p_anio" integer, "p_aviso" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prest uuid := interno.prestadora_actual();
BEGIN
  IF v_prest IS NULL OR COALESCE(auth.jwt() ->> 'role', '') <> 'trabajo_sin_persona' THEN
    RAISE EXCEPTION 'sin_permiso_para_avisar_el_borrado_de_las_consultas_a_hce' USING ERRCODE = '42501';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('aviso_de_borrado:' || v_prest::text, 0));

  IF NOT EXISTS (
    SELECT 1 FROM interno.aviso_de_borrado_de_consultas_a_hce_pendiente(v_prest) p
     WHERE p.anio = p_anio AND p.aviso = p_aviso) THEN
    RETURN false;
  END IF;

  INSERT INTO registro_actividad (prestadora_id, usuario_id, accion, tabla_afectada, registro_id, detalle)
  VALUES (v_prest, NULL, p_aviso || '_de_borrado', 'consultas_a_hce', NULL, jsonb_build_object('anio', p_anio));
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."anotar_aviso_de_borrado_de_consultas_a_hce"("p_anio" integer, "p_aviso" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."asignar_serie"("p_serie_id" "uuid", "p_asistente_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid := interno.prestadora_actual();
  v_serie      public.series_guardias;
  v_pendiente  public.asignaciones_de_turno;
  v_anterior   uuid;
  v_nueva      uuid;
  v_bloquean   text[];
BEGIN
  IF v_prestadora IS NULL THEN
    RAISE EXCEPTION 'serie_no_encontrada';
  END IF;

  SELECT * INTO v_pendiente
    FROM asignaciones_de_turno
   WHERE serie_id = p_serie_id
     AND prestadora_id = v_prestadora
     AND estado = 'sin_responder'
   FOR UPDATE;

  SELECT * INTO v_serie
    FROM series_guardias
   WHERE id = p_serie_id
     AND prestadora_id = v_prestadora
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'serie_no_encontrada';
  END IF;

  IF v_serie.estado <> 'activa' THEN
    RAISE EXCEPTION 'serie_no_se_asigna' USING ERRCODE = '23514';
  END IF;

  IF p_asistente_id IS NOT NULL AND v_pendiente.asistente_id = p_asistente_id THEN
    RETURN jsonb_build_object('sin_cambios', true);
  END IF;
  IF p_asistente_id IS NOT NULL AND v_pendiente.id IS NULL AND v_serie.asistente_id = p_asistente_id THEN
    RETURN jsonb_build_object('sin_cambios', true);
  END IF;
  IF p_asistente_id IS NULL AND v_pendiente.id IS NULL AND v_serie.asistente_id IS NULL THEN
    RETURN jsonb_build_object('sin_cambios', true);
  END IF;

  v_anterior := COALESCE(v_serie.asistente_id, v_pendiente.asistente_anterior_id);

  IF p_asistente_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM asistentes a WHERE a.id = p_asistente_id AND a.prestadora_id = v_prestadora) THEN
      RAISE EXCEPTION 'asistente_no_encontrado';
    END IF;

    IF EXISTS (SELECT 1 FROM usuarios u WHERE u.id = interno.usuario_de_la_sesion() AND u.rol = 'coordinador')
       AND NOT interno.coordinador_alcanza_asistente(p_asistente_id) THEN
      RAISE EXCEPTION 'asistente_no_encontrado';
    END IF;

    v_bloquean := interno.documentos_que_bloquean(
      p_asistente_id, GREATEST(v_serie.vigente_desde, CURRENT_DATE), v_serie.paciente_id, v_serie.servicio_id);
    IF cardinality(v_bloquean) > 0 THEN
      RAISE EXCEPTION 'documentos_bloquean:%:', array_to_string(v_bloquean, ', ') USING ERRCODE = '23514';
    END IF;

    IF v_serie.canal_modalidad IS NOT NULL
       AND NOT interno.asistente_trabaja_en_modalidad(p_asistente_id, v_serie.canal_modalidad) THEN
      RAISE EXCEPTION 'modalidad_bloquea:%:', v_serie.canal_modalidad USING ERRCODE = '23514';
    END IF;
  END IF;

  IF v_pendiente.id IS NOT NULL THEN
    UPDATE asignaciones_de_turno SET estado = 'retirada' WHERE id = v_pendiente.id;
  END IF;

  IF v_serie.asistente_id IS NOT NULL THEN
    UPDATE series_guardias SET asistente_id = NULL WHERE id = v_serie.id;
  END IF;

  IF p_asistente_id IS NOT NULL THEN
    INSERT INTO asignaciones_de_turno (prestadora_id, serie_id, asistente_id, asistente_anterior_id)
    VALUES (v_prestadora, v_serie.id, p_asistente_id, v_anterior)
    RETURNING id INTO v_nueva;
  END IF;

  RETURN jsonb_build_object(
    'sin_cambios', false,
    'asignacion_id', v_nueva,
    'titular_retirado', v_serie.asistente_id,
    'pendiente_retirado', v_pendiente.asistente_id,
    'asistente_anterior_id', v_anterior
  );
END;
$$;


ALTER FUNCTION "public"."asignar_serie"("p_serie_id" "uuid", "p_asistente_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."asignar_turno"("p_guardia_id" "uuid", "p_asistente_id" "uuid", "p_motivo_excepcion" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid := interno.prestadora_actual();
  v_guardia    public.guardias;
  v_pendiente  public.asignaciones_de_turno;
  v_anterior   uuid;
  v_nueva      uuid;
BEGIN
  IF v_prestadora IS NULL THEN
    RAISE EXCEPTION 'guardia_no_encontrada';
  END IF;

  -- Primero la asignación pendiente y después el turno: es el mismo orden en que los toma
  -- `aceptar_asignacion`, así las dos nunca se esperan una a la otra.
  SELECT * INTO v_pendiente
    FROM asignaciones_de_turno
   WHERE guardia_id = p_guardia_id
     AND prestadora_id = v_prestadora
     AND estado = 'sin_responder'
   FOR UPDATE;

  SELECT * INTO v_guardia
    FROM guardias
   WHERE id = p_guardia_id
     AND prestadora_id = v_prestadora
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'guardia_no_encontrada';
  END IF;

  IF v_guardia.estado <> 'programada' THEN
    RAISE EXCEPTION 'guardia_no_se_asigna' USING ERRCODE = '23514';
  END IF;

  -- Lo que ya está como se pide no se toca: ni se retira ni se vuelve a avisar.
  IF p_asistente_id IS NOT NULL AND v_pendiente.asistente_id = p_asistente_id THEN
    RETURN jsonb_build_object('sin_cambios', true);
  END IF;
  IF p_asistente_id IS NULL AND v_pendiente.id IS NULL AND v_guardia.asistente_id IS NULL THEN
    RETURN jsonb_build_object('sin_cambios', true);
  END IF;

  v_anterior := COALESCE(v_guardia.asistente_id, v_pendiente.asistente_anterior_id);

  -- Las mismas paredes que pone la base cuando el turno pasa a ser de alguien, puestas ahora,
  -- para que el Coordinador se entere al asignar y no el Asistente al aceptar.
  IF p_asistente_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM asistentes a WHERE a.id = p_asistente_id AND a.prestadora_id = v_prestadora) THEN
      RAISE EXCEPTION 'asistente_no_encontrado';
    END IF;

    -- El Coordinador asigna sólo a los Asistentes de su zona. Lo frenaría igual la política de
    -- la asignación, pero con un error que no dice qué pasó.
    IF EXISTS (SELECT 1 FROM usuarios u WHERE u.id = interno.usuario_de_la_sesion() AND u.rol = 'coordinador')
       AND NOT interno.coordinador_alcanza_asistente(p_asistente_id) THEN
      RAISE EXCEPTION 'asistente_no_encontrado';
    END IF;

    PERFORM interno.excepcion_por_documentos(
      v_prestadora,
      v_guardia.id,
      p_asistente_id,
      interno.documentos_que_bloquean(
        p_asistente_id,
        interno.dia_en_que_termina_guardia(v_guardia.fecha, v_guardia.hora_inicio, v_guardia.hora_fin, v_guardia.dias_hasta_el_fin),
        v_guardia.paciente_id,
        v_guardia.servicio_id
      ),
      p_motivo_excepcion
    );

    IF v_guardia.canal_modalidad IS NOT NULL
       AND NOT interno.asistente_trabaja_en_modalidad(p_asistente_id, v_guardia.canal_modalidad) THEN
      RAISE EXCEPTION 'modalidad_bloquea:%:', v_guardia.canal_modalidad USING ERRCODE = '23514';
    END IF;
  END IF;

  IF v_pendiente.id IS NOT NULL THEN
    UPDATE asignaciones_de_turno SET estado = 'retirada' WHERE id = v_pendiente.id;
  END IF;

  IF v_guardia.asistente_id IS NOT NULL THEN
    UPDATE guardias SET asistente_id = NULL WHERE id = v_guardia.id;
  END IF;

  IF p_asistente_id IS NOT NULL THEN
    INSERT INTO asignaciones_de_turno (prestadora_id, guardia_id, asistente_id, asistente_anterior_id)
    VALUES (v_prestadora, v_guardia.id, p_asistente_id, v_anterior)
    RETURNING id INTO v_nueva;
  END IF;

  -- Alguien perdió el turno: la alarma se abre ya. Si había una abierta, sigue la misma.
  IF v_guardia.asistente_id IS NOT NULL OR v_pendiente.id IS NOT NULL THEN
    INSERT INTO incidentes_turno_sin_cubrir (prestadora_id, guardia_id)
    VALUES (v_prestadora, v_guardia.id)
    ON CONFLICT (guardia_id) WHERE resuelto_at IS NULL DO NOTHING;
  END IF;

  RETURN jsonb_build_object(
    'sin_cambios', false,
    'asignacion_id', v_nueva,
    'titular_retirado', v_guardia.asistente_id,
    'pendiente_retirado', v_pendiente.asistente_id,
    'asistente_anterior_id', v_anterior
  );
END;
$$;


ALTER FUNCTION "public"."asignar_turno"("p_guardia_id" "uuid", "p_asistente_id" "uuid", "p_motivo_excepcion" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."asistente_asignado_a_cliente"("p_asistente_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM guardias g
    JOIN pacientes p ON p.id = g.paciente_id
    WHERE g.asistente_id = p_asistente_id
      AND p.cliente_id = cliente_id_de_usuario(auth.uid())
  );
$$;


ALTER FUNCTION "public"."asistente_asignado_a_cliente"("p_asistente_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."asistente_asignado_a_cliente"("p_asistente_id" "uuid") IS 'Única fuente de verdad para saber si un Asistente atiende a un Paciente del Cliente de la sesión. Va por función y no dentro de la política para no armar una referencia circular entre asistentes y guardias.';



CREATE OR REPLACE FUNCTION "public"."asistentes_asignados_al_paciente"("p_paciente" "uuid") RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT DISTINCT g.asistente_id
    FROM guardia_pacientes gp
    JOIN guardias g ON g.id = gp.guardia_id AND g.prestadora_id = gp.prestadora_id
   WHERE gp.paciente_id = p_paciente
     AND gp.prestadora_id = interno.prestadora_actual()
     AND interno.es_personal_de_la_prestadora()
     AND g.asistente_id IS NOT NULL
     AND g.fecha >= current_date;
$$;


ALTER FUNCTION "public"."asistentes_asignados_al_paciente"("p_paciente" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ausencias_que_tapan"("p_desde" "date", "p_hasta" "date", "p_hoy" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("asistente_id" "uuid", "fecha_inicio" "date", "fecha_fin" "date")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  WITH efectivas AS (
    SELECT a.asistente_id, a.fecha_inicio,
           CASE WHEN a.fecha_vuelta_real IS NULL AND a.fecha_fin < p_hoy THEN NULL
                ELSE a.fecha_fin END AS fecha_fin
    FROM public.ausencias a
    JOIN public.asistentes s ON s.id = a.asistente_id
    WHERE
      -- El aislamiento, primero y adentro: la licencia y la persona, las dos de esta Prestadora.
      a.prestadora_id = prestadora_actual()
      AND s.prestadora_id = prestadora_actual()
      -- Quién tiene derecho a preguntar: los tres roles de Panel y nadie más.
      AND (
        es_superadmin()
        OR es_admin_prestadora()
        OR EXISTS (SELECT 1 FROM public.usuarios u WHERE u.id = auth.uid() AND u.rol = 'coordinador')
      )
  )
  SELECT e.asistente_id, e.fecha_inicio, e.fecha_fin
  FROM efectivas e
  WHERE e.fecha_inicio <= p_hasta
    AND (e.fecha_fin IS NULL OR e.fecha_fin >= p_desde);
$$;


ALTER FUNCTION "public"."ausencias_que_tapan"("p_desde" "date", "p_hasta" "date", "p_hoy" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aviso_de_borrado_de_consultas_a_hce_pendiente"() RETURNS TABLE("anio" integer, "se_borra_el" "date", "aviso" "text", "dias" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prest uuid := interno.prestadora_actual();
BEGIN
  IF v_prest IS NULL OR COALESCE(auth.jwt() ->> 'role', '') <> 'trabajo_sin_persona' THEN
    RAISE EXCEPTION 'sin_permiso_para_avisar_el_borrado_de_las_consultas_a_hce' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT * FROM interno.aviso_de_borrado_de_consultas_a_hce_pendiente(v_prest);
END;
$$;


ALTER FUNCTION "public"."aviso_de_borrado_de_consultas_a_hce_pendiente"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bloquear_edicion_laboral_coordinador"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  rol_actual TEXT;
BEGIN
  SELECT rol INTO rol_actual FROM usuarios WHERE id = interno.usuario_de_la_sesion();

  IF rol_actual = 'coordinador' THEN
    IF NEW.horas_semanales IS DISTINCT FROM OLD.horas_semanales
      OR NEW.fecha_baja IS DISTINCT FROM OLD.fecha_baja
    THEN
      RAISE EXCEPTION 'Coordinador no puede modificar datos laborales internos del Asistente';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."bloquear_edicion_laboral_coordinador"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."borrar_consultas_a_hce_vencidas"() RETURNS TABLE("anio" integer, "renglones" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prest    uuid := interno.prestadora_actual();
  v          record;
  v_hasta    record;
  v_cuantos  bigint;
  v_corte    uuid;
BEGIN
  IF v_prest IS NULL OR COALESCE(auth.jwt() ->> 'role', '') <> 'trabajo_sin_persona' THEN
    RAISE EXCEPTION 'sin_permiso_para_borrar_las_consultas_a_hce' USING ERRCODE = '42501';
  END IF;

  -- El mismo candado que la anotación: mientras se borra, nadie se cuelga de un renglón que se va.
  PERFORM pg_advisory_xact_lock(hashtextextended('consultas_a_hce:' || v_prest::text, 0));

  LOOP
    SELECT * INTO v FROM interno.consultas_a_hce_por_vencer(v_prest);
    EXIT WHEN v.anio IS NULL OR v.se_borra_el > current_date;

    SELECT a.numero, a.resumen INTO v_hasta
      FROM consultas_a_hce a
     WHERE a.prestadora_id = v_prest AND a.momento < v.hasta
     ORDER BY a.numero DESC
     LIMIT 1;

    SELECT count(*) INTO v_cuantos
      FROM consultas_a_hce a
     WHERE a.prestadora_id = v_prest AND a.numero <= v_hasta.numero;

    INSERT INTO cortes_de_consultas_a_hce (prestadora_id, anio, hasta_numero, ultimo_resumen, renglones)
    VALUES (v_prest, v.anio, v_hasta.numero, v_hasta.resumen, v_cuantos)
    RETURNING id INTO v_corte;

    DELETE FROM consultas_a_hce a
     WHERE a.prestadora_id = v_prest AND a.numero <= v_hasta.numero;

    INSERT INTO registro_actividad (prestadora_id, usuario_id, accion, tabla_afectada, registro_id, detalle)
    VALUES (v_prest, NULL, 'borrado_por_vencimiento', 'consultas_a_hce', v_corte,
            jsonb_build_object('anio', v.anio, 'renglones', v_cuantos, 'hasta_numero', v_hasta.numero));

    anio := v.anio;
    renglones := v_cuantos;
    RETURN NEXT;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."borrar_consultas_a_hce_vencidas"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cerrar_autorizacion_signos_vitales_con_documento_firmado"("p_paciente" "uuid", "p_archivo" "text", "p_idioma" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_quien uuid := auth.uid();
  v_prestadora uuid := interno.prestadora_actual();
  v_doc record;
  v_id uuid;
BEGIN
  IF v_quien IS NULL OR NOT interno.es_personal_de_la_prestadora() THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pacientes WHERE id = p_paciente AND prestadora_id = v_prestadora)
     OR NOT interno.alcanza_la_informacion_de_salud(p_paciente) THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  IF p_archivo NOT LIKE v_prestadora::text || '/' || p_paciente::text || '/autorizacion-%' THEN
    RAISE EXCEPTION 'archivo_invalido' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM autorizaciones_monitoreo_paciente
              WHERE paciente_id = p_paciente AND estado IN ('aceptada', 'pendiente')) THEN
    RAISE EXCEPTION 'ya_hay_una_autorizacion' USING ERRCODE = '23505';
  END IF;

  SELECT * INTO v_doc FROM interno.documento_autorizacion_signos_vitales(p_paciente, p_idioma);
  IF v_doc.texto IS NULL THEN
    RAISE EXCEPTION 'sin_texto' USING ERRCODE = '22023';
  END IF;

  INSERT INTO autorizaciones_monitoreo_paciente
    (prestadora_id, paciente_id, metodo, estado, documento_texto, documento_verificador, documento_idioma,
     firmante_persona_id, archivo_url, cargado_por, revisado_por, revisado_en)
  VALUES
    (v_prestadora, p_paciente, 'documento_firmado_panel', 'aceptada', v_doc.texto, v_doc.verificador, p_idioma,
     interno.firmante_autorizacion_signos_vitales(p_paciente), p_archivo, v_quien, v_quien, now())
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."cerrar_autorizacion_signos_vitales_con_documento_firmado"("p_paciente" "uuid", "p_archivo" "text", "p_idioma" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cerrar_firma_medicacion_con_documento_firmado"("p_firma" "uuid", "p_archivo" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT interno.es_personal_de_la_prestadora() THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;

  UPDATE consentimientos_medicacion c
     SET estado = 'cerrado',
         cerrado_como = 'documento_firmado',
         cerrado_en = now(),
         cerrado_desde = 'panel',
         archivo_firmado_url = p_archivo
    FROM indicaciones_medicacion i
   WHERE c.id = p_firma
     AND c.prestadora_id = interno.prestadora_actual()
     AND c.estado = 'pendiente_firma'
     AND i.id = c.indicacion_id
     AND i.prestadora_id = c.prestadora_id
     AND interno.alcanza_la_informacion_de_salud(i.paciente_id)
     AND p_archivo LIKE c.prestadora_id::text || '/firmas-medicacion/' || i.paciente_id::text || '/firma-' || c.id::text || '.%';
  RETURN FOUND;
END;
$$;


ALTER FUNCTION "public"."cerrar_firma_medicacion_con_documento_firmado"("p_firma" "uuid", "p_archivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cerrar_hospitalizacion"("p_hospitalizacion" "uuid", "p_fecha" "date") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_antes    text := coalesce(current_setting('careonys.lectura_de_salud', true), '');
  v_paciente uuid;
  v_inicio   date;
BEGIN
  PERFORM set_config('careonys.lectura_de_salud', 'anotada', true);
  UPDATE hospitalizaciones_paciente h
     SET fecha_fin = greatest(p_fecha, h.fecha_inicio)
   WHERE h.id = p_hospitalizacion
     AND h.prestadora_id = interno.prestadora_actual()
     AND h.fecha_fin IS NULL
  RETURNING h.paciente_id, h.fecha_inicio INTO v_paciente, v_inicio;
  PERFORM set_config('careonys.lectura_de_salud', v_antes, true);
  IF v_paciente IS NULL THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  PERFORM interno.anotar_lo_que_se_leyo('hospitalizaciones_paciente', ARRAY[v_paciente], 'cerrar_hospitalizacion');

  IF EXISTS (SELECT 1 FROM domicilios_temporales_paciente d WHERE d.hospitalizacion_id = p_hospitalizacion) THEN
    UPDATE domicilios_temporales_paciente d
       SET fecha_fin = greatest(p_fecha, d.fecha_inicio)
     WHERE d.hospitalizacion_id = p_hospitalizacion
       AND (d.fecha_fin IS NULL OR d.fecha_fin > greatest(p_fecha, d.fecha_inicio));
  ELSE
    UPDATE guardias SET estado = 'programada' WHERE paciente_id = v_paciente AND estado = 'pausada';
    UPDATE series_guardias SET estado = 'activa' WHERE paciente_id = v_paciente AND estado = 'pausada';
  END IF;
END;
$$;


ALTER FUNCTION "public"."cerrar_hospitalizacion"("p_hospitalizacion" "uuid", "p_fecha" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."completar_genero_de_la_persona"("p_persona" "uuid", "p_genero" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
BEGIN
  IF interno.prestadora_actual() IS NULL
     OR NOT (auth.jwt() ->> 'role' = 'trabajo_sin_persona' OR interno.es_personal_de_la_prestadora()) THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
