CREATE OR REPLACE FUNCTION "public"."consumir_contacto_intermediacion"("p_acceso_id" "uuid", "p_asistente_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_acceso public.accesos_intermediacion%ROWTYPE;
  v_ya_estaba boolean;
  v_saldo integer;
BEGIN
  -- Tomada la fila del acceso, el que llegue segundo espera acá. Sin esto, dos pedidos leen el
  -- mismo saldo y los dos descuentan sobre ese número: de dos contactos se cobra uno.
  SELECT * INTO v_acceso
    FROM public.accesos_intermediacion
   WHERE id = p_acceso_id
     FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'acceso_inexistente');
  END IF;

  -- Falla cerrado: un acceso vencido o dado de baja no abre nada, aunque le haya quedado saldo.
  IF v_acceso.estado <> 'vigente' THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'acceso_no_vigente');
  END IF;

  -- Ya abierto antes: se contesta que sí y no se cobra de nuevo. El contacto de un Asistente se
  -- paga una sola vez por Cliente, y mirarlo otra vez no es un contacto nuevo.
  SELECT EXISTS (
    SELECT 1 FROM public.contactos_vistos_intermediacion
     WHERE cliente_id = v_acceso.cliente_id AND asistente_id = p_asistente_id
  ) INTO v_ya_estaba;

  IF v_ya_estaba THEN
    RETURN jsonb_build_object(
      'ok', true, 'ya_estaba', true, 'saldo_contactos', v_acceso.saldo_contactos
    );
  END IF;

  IF v_acceso.saldo_contactos IS NOT NULL AND v_acceso.saldo_contactos <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'saldo_agotado', 'saldo_contactos', 0);
  END IF;

  -- Se anota primero y se descuenta después, en ese orden y no al revés: así el candado de la
  -- tabla es el que decide, y no queda ninguna forma de descontar sin haber anotado. La misma
  -- Cliente con dos paquetes abriendo el mismo Asistente a la vez llega hasta acá por dos filas
  -- de acceso distintas, que el candado de más arriba no cruza; el segundo choca contra éste.
  BEGIN
    INSERT INTO public.contactos_vistos_intermediacion
      (prestadora_id, cliente_id, asistente_id, acceso_id)
    VALUES
      (v_acceso.prestadora_id, v_acceso.cliente_id, p_asistente_id, p_acceso_id);
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object(
      'ok', true, 'ya_estaba', true, 'saldo_contactos', v_acceso.saldo_contactos
    );
  END;

  -- El que se sostiene por fecha no tiene qué descontar: queda anotado y el saldo sigue vacío.
  IF v_acceso.saldo_contactos IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'ya_estaba', false, 'saldo_contactos', NULL);
  END IF;

  UPDATE public.accesos_intermediacion
     SET saldo_contactos = saldo_contactos - 1,
         updated_at = now()
   WHERE id = p_acceso_id
  RETURNING saldo_contactos INTO v_saldo;

  RETURN jsonb_build_object('ok', true, 'ya_estaba', false, 'saldo_contactos', v_saldo);
END;
$$;


ALTER FUNCTION "public"."consumir_contacto_intermediacion"("p_acceso_id" "uuid", "p_asistente_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."consumir_contacto_intermediacion"("p_acceso_id" "uuid", "p_asistente_id" "uuid") IS 'Anota a qué Asistente se le abrió el contacto y, si el acceso se sostiene por saldo, le descuenta uno, en la misma transacción. Un Asistente ya abierto no vuelve a descontar. El acceso que se sostiene por fecha se anota sin descontar nada. Devuelve ok y el saldo que queda, o el motivo por el que no se pudo.';



CREATE OR REPLACE FUNCTION "public"."correcciones_de_factura"("p_factura_id" "uuid") RETURNS TABLE("neto" numeric, "correcciones_contadas" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT
    COALESCE(SUM(CASE WHEN c.sentido = 'resta' THEN -c.monto ELSE c.monto END), 0)::numeric(12, 2),
    COUNT(*)::integer
  FROM public.correcciones_factura_cliente c
  WHERE c.factura_id = p_factura_id;
$$;


ALTER FUNCTION "public"."correcciones_de_factura"("p_factura_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."correcciones_de_factura"("p_factura_id" "uuid") IS 'Cuanto movieron en total las correcciones de una factura, y cuantas fueron. Negativo es que se facturo de mas.';



CREATE OR REPLACE FUNCTION "public"."cuenta_del_usuario"("p_usuario" "text") RETURNS TABLE("id" "uuid", "prestadora_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT u.id, u.prestadora_id
    FROM usuarios u
   WHERE auth.jwt() ->> 'role' = 'trabajo_sin_persona'
     AND u.rol IN ('coordinador', 'asistente', 'cliente')
     AND u.desactivada_en IS NULL
     AND u.nombre_de_usuario IS NOT NULL
     AND lower(u.nombre_de_usuario) = lower(btrim(coalesce(p_usuario, ''), E' \t\r\n'));
$$;


ALTER FUNCTION "public"."cuenta_del_usuario"("p_usuario" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."asistentes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "nombre" "text" NOT NULL,
    "telefono" "text",
    "email" "text",
    "foto_url" "text",
    "disponibilidad" "jsonb",
    "estado" "text" DEFAULT 'activo'::"text" NOT NULL,
    "qr_token" "text" DEFAULT ("gen_random_uuid"())::"text",
    "fecha_alta" "date" DEFAULT CURRENT_DATE NOT NULL,
    "fecha_baja" "date",
    "horas_semanales" numeric(5,2),
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "deleted_at" timestamp with time zone,
    "dni" "text",
    "prestadora_id" "uuid" NOT NULL,
    "canales" "text"[] DEFAULT ARRAY['directa'::"text", 'intermediacion'::"text"] NOT NULL,
    "importacion_id" "uuid",
    "pendiente_conformidad" boolean DEFAULT false NOT NULL,
    "tipo_asistente_id" "uuid",
    "disponible" boolean DEFAULT true NOT NULL,
    "disponibilidad_cambiada_en" timestamp with time zone,
    "usuario_id" "uuid" NOT NULL,
    "numero_legajo" integer NOT NULL,
    "documento_tipo" "text",
    "documento_numero" "text",
    "documento_pais" "text",
    "genero" "text",
    CONSTRAINT "asistentes_canales_valido" CHECK ((("canales" <@ ARRAY['directa'::"text", 'intermediacion'::"text"]) AND ("array_length"("canales", 1) > 0))),
    CONSTRAINT "asistentes_estado_check" CHECK (("estado" = ANY (ARRAY['activo'::"text", 'inactivo'::"text", 'cesado'::"text"])))
);


ALTER TABLE "public"."asistentes" OWNER TO "postgres";


COMMENT ON COLUMN "public"."asistentes"."canales" IS 'En qué modalidades de trabajo está este Asistente: directa, match, o las dos. Tiene que estar dentro de lo que la Prestadora tenga habilitado. El nombre de la columna quedó de antes y no se renombra; la palabra del producto es modalidad de trabajo.';



COMMENT ON COLUMN "public"."asistentes"."tipo_asistente_id" IS 'Que ES este Asistente: cuidador/a, enfermero/a, kinesiologo/a, medico/a o el tipo que haya creado su Prestadora. Decide sus Tareas y si se le exige Matricula vigente para atender.';



COMMENT ON COLUMN "public"."asistentes"."disponible" IS 'Lo decide el Asistente desde su aplicacion, no la Prestadora. En false, el aviso automatico de relevo no le escribe y en la lista de candidatos queda con su motivo. No cambia ningun turno ya asignado. Distinto de asistentes.estado, que es la decision administrativa de la Prestadora.';



COMMENT ON COLUMN "public"."asistentes"."disponibilidad_cambiada_en" IS 'Cuando lo cambio por ultima vez. Sirve para que quien coordina sepa si el "no disponible" es de hoy o de hace tres meses.';



COMMENT ON COLUMN "public"."asistentes"."usuario_id" IS 'De qué cuenta cuelga esta ficha. Una cuenta puede tener una ficha por Prestadora; la ficha es el legajo de trabajo en esa Prestadora y la cuenta es la persona.';



CREATE OR REPLACE FUNCTION "public"."cuenta_desactivada"("a" "public"."asistentes") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT CASE
    WHEN interno.prestadora_actual() IS NOT NULL
         AND interno.prestadora_actual() IS DISTINCT FROM a.prestadora_id THEN false
    ELSE interno.asistente_desactivado(a.id)
  END;
$$;


ALTER FUNCTION "public"."cuenta_desactivada"("a" "public"."asistentes") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cuentas_nunca_activadas"("p_usuarios" "uuid"[]) RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT u.id
  FROM public.usuarios u
  JOIN auth.users a ON a.id = u.id
  WHERE auth.jwt() ->> 'role' = 'trabajo_sin_persona'
    AND u.prestadora_id = interno.prestadora_actual()
    AND u.id = ANY (p_usuarios)
    AND a.last_sign_in_at IS NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.tokens_activacion_cuenta t
      WHERE t.usuario_id = u.id
        AND t.usado_en IS NOT NULL
    );
$$;


ALTER FUNCTION "public"."cuentas_nunca_activadas"("p_usuarios" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dar_de_alta_la_cuenta"("p_email" "text", "p_clave" "text", "p_rol" "text", "p_nombre" "text", "p_telefono" "text", "p_nombre_de_usuario" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $_$
DECLARE
  v_prestadora uuid;
  v_correo text;
  v_usuario uuid := gen_random_uuid();
  v_ingreso text;
  v_parte text;
  v_dominio text;
  v_nombre_de_usuario text;
BEGIN
  IF auth.jwt() ->> 'role' IS DISTINCT FROM 'trabajo_sin_persona' THEN
    RAISE EXCEPTION 'sin_permiso';
  END IF;
  v_prestadora := interno.prestadora_actual();
  IF v_prestadora IS NULL THEN RAISE EXCEPTION 'sin_permiso'; END IF;
  IF p_rol IS NULL OR p_rol NOT IN ('coordinador', 'asistente', 'cliente') THEN
    RAISE EXCEPTION 'sin_permiso';
  END IF;
  v_correo := lower(btrim(coalesce(p_email, ''), E' \t\r\n'));
  IF v_correo = '' OR coalesce(p_clave, '') = '' THEN RAISE EXCEPTION 'faltan_datos'; END IF;

  IF EXISTS (SELECT 1 FROM usuarios WHERE prestadora_id = v_prestadora AND lower(email) = v_correo
                AND desactivada_en IS NULL) THEN
    RAISE EXCEPTION 'correo_de_esta_prestadora';
  END IF;

  -- La coordinación nace con su nombre: la parte que escribe el Administrador y el código de la
  -- Prestadora. Asistentes y Clientes eligen el suyo al activar la cuenta.
  IF p_rol = 'coordinador' THEN
    v_parte := nullif(lower(btrim(coalesce(p_nombre_de_usuario, ''), E' \t\r\n')), '');
    IF v_parte IS NULL THEN RAISE EXCEPTION 'faltan_datos'; END IF;
    IF v_parte !~ '^[a-z0-9]([a-z0-9._-]{0,38}[a-z0-9])?$' THEN
      RAISE EXCEPTION 'usuario_mal_escrito';
    END IF;
    SELECT dominio INTO v_dominio FROM configuracion_prestadora WHERE prestadora_id = v_prestadora;
    IF v_dominio IS NULL THEN RAISE EXCEPTION 'faltan_datos'; END IF;
    v_nombre_de_usuario := v_parte || '_' || lower(v_dominio);
    IF EXISTS (SELECT 1 FROM usuarios WHERE lower(nombre_de_usuario) = v_nombre_de_usuario
                  AND desactivada_en IS NULL) THEN
      RAISE EXCEPTION 'usuario_en_uso';
    END IF;
  END IF;

  v_ingreso := v_usuario::text || '@acceso.careonys.invalid';

  INSERT INTO auth.users (
    instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
    raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
    confirmation_token, recovery_token, email_change_token_new, email_change,
    email_change_token_current, phone_change, phone_change_token, reauthentication_token)
  VALUES (
    '00000000-0000-0000-0000-000000000000', v_usuario, 'authenticated', 'authenticated',
    v_ingreso, extensions.crypt(p_clave, extensions.gen_salt('bf', 10)), now(),
    '{"provider":"email","providers":["email"]}'::jsonb, '{}'::jsonb, now(), now(),
    '', '', '', '', '', '', '', '');
  INSERT INTO auth.identities (
    provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
  VALUES (
    v_usuario::text, v_usuario,
    jsonb_build_object('sub', v_usuario::text, 'email', v_ingreso, 'email_verified', true),
    'email', NULL, now(), now());
  BEGIN
    INSERT INTO usuarios (id, rol, nombre, telefono, email, prestadora_id, nombre_de_usuario)
    VALUES (v_usuario, p_rol, p_nombre, nullif(btrim(coalesce(p_telefono, '')), ''), v_correo, v_prestadora,
            v_nombre_de_usuario);
  EXCEPTION WHEN unique_violation THEN
    -- Dos altas al mismo tiempo pasaron las dos comprobaciones de arriba: el índice decide.
    IF v_nombre_de_usuario IS NOT NULL
       AND EXISTS (SELECT 1 FROM usuarios WHERE lower(nombre_de_usuario) = v_nombre_de_usuario
                      AND desactivada_en IS NULL) THEN
      RAISE EXCEPTION 'usuario_en_uso';
    END IF;
    RAISE EXCEPTION 'correo_de_esta_prestadora';
  END;
  RETURN v_usuario;
END;
$_$;


ALTER FUNCTION "public"."dar_de_alta_la_cuenta"("p_email" "text", "p_clave" "text", "p_rol" "text", "p_nombre" "text", "p_telefono" "text", "p_nombre_de_usuario" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dar_de_baja_el_servicio"("p_servicio" "uuid", "p_motivo" "text", "p_motivo_detalle" "text", "p_comprobaciones" "uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_servicio servicios%ROWTYPE;
  v_pide_detalle boolean;
  v_comprobaciones text[];
  v_faltan integer;
  v_baja uuid;
BEGIN
  SELECT * INTO v_servicio FROM servicios
   WHERE id = p_servicio AND prestadora_id = interno.prestadora_actual();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'servicio_inexistente';
  END IF;
  IF v_servicio.estado <> 'vigente' THEN
    RAISE EXCEPTION 'el_servicio_ya_esta_de_baja';
  END IF;

  IF interno.guardias_asignadas_del_servicio(p_servicio) > 0 THEN
    RAISE EXCEPTION 'el_servicio_tiene_guardias_asignadas';
  END IF;

  SELECT m.pide_detalle INTO v_pide_detalle
    FROM motivos_cierre_servicio m
   WHERE m.prestadora_id = v_servicio.prestadora_id
     AND m.activo
     AND coalesce(m.clave, m.nombre) = p_motivo
   LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'motivo_de_cierre_inexistente:%', p_motivo;
  END IF;
  IF v_pide_detalle AND coalesce(btrim(p_motivo_detalle), '') = '' THEN
    RAISE EXCEPTION 'motivo_de_cierre_pide_detalle:%', p_motivo;
  END IF;

  SELECT count(*) INTO v_faltan
    FROM lista_de_comprobacion_baja_servicio l
   WHERE l.prestadora_id = v_servicio.prestadora_id
     AND l.activo
     AND NOT (l.id = ANY (coalesce(p_comprobaciones, '{}')));
  IF v_faltan > 0 THEN
    RAISE EXCEPTION 'faltan_comprobaciones_de_la_baja';
  END IF;

  SELECT coalesce(array_agg(l.nombre ORDER BY l.orden, l.created_at), '{}') INTO v_comprobaciones
    FROM lista_de_comprobacion_baja_servicio l
   WHERE l.prestadora_id = v_servicio.prestadora_id
     AND l.activo
     AND l.id = ANY (coalesce(p_comprobaciones, '{}'));

  INSERT INTO bajas_de_servicio (prestadora_id, servicio_id, motivo, motivo_detalle, comprobaciones, dada_por)
  VALUES (v_servicio.prestadora_id, p_servicio, p_motivo,
          CASE WHEN v_pide_detalle THEN btrim(p_motivo_detalle) END,
          v_comprobaciones, interno.usuario_de_la_sesion())
  RETURNING id INTO v_baja;

  -- La fecha de fin de cada prestación la pone la base al ver la baja.
  UPDATE prestaciones SET estado = 'de_baja'
   WHERE servicio_id = p_servicio AND estado = 'vigente';
  UPDATE series_guardias
     SET estado = 'cancelada', cancelacion_origen = 'prestadora', cancelado_at = now()
   WHERE servicio_id = p_servicio AND estado = 'activa';
  UPDATE guardias
     SET estado = 'cancelada', cancelacion_origen = 'prestadora', cancelacion_alcance = 'total'
   WHERE servicio_id = p_servicio AND estado = 'programada' AND asistente_id IS NULL;

  PERFORM set_config('careonys.cambio_de_estado_del_servicio', p_servicio::text, true);
  UPDATE servicios SET estado = 'de_baja' WHERE id = p_servicio;
  PERFORM set_config('careonys.cambio_de_estado_del_servicio', '', true);

  PERFORM interno.anotar_deuda_de_la_baja(v_baja);

  RETURN v_baja;
END;
$$;


ALTER FUNCTION "public"."dar_de_baja_el_servicio"("p_servicio" "uuid", "p_motivo" "text", "p_motivo_detalle" "text", "p_comprobaciones" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."desactivar_la_cuenta"("p_usuario" "uuid", "p_motivo" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid;
  v_motivo text := btrim(coalesce(p_motivo, ''), E' \t\r\n');
BEGIN
  IF auth.jwt() ->> 'role' IS DISTINCT FROM 'trabajo_sin_persona' THEN RETURN false; END IF;
  v_prestadora := interno.prestadora_actual();
  IF v_prestadora IS NULL OR p_usuario IS NULL OR v_motivo = '' THEN RETURN false; END IF;

  -- Turnos sin terminar: se reasignan o se cierran antes, y la cuenta queda como estaba.
  IF EXISTS (SELECT 1 FROM interno.turnos_que_traban_la_desactivacion(p_usuario, v_prestadora)) THEN
    RAISE EXCEPTION 'desactivacion_con_turnos_por_delante';
  END IF;

  UPDATE usuarios
     SET desactivada_en = now(),
         motivo_de_la_desactivacion = v_motivo
   WHERE id = p_usuario
     AND prestadora_id = v_prestadora
     AND rol IN ('coordinador', 'asistente', 'cliente')
     AND desactivada_en IS NULL;
  IF NOT FOUND THEN RETURN false; END IF;

  -- La cuenta de ingreso queda bloqueada: no entra con la clave, no renueva la sesión y no canjea
  -- ningún enlace. El bloqueo no lo levanta un cambio de clave.
  UPDATE auth.users
     SET banned_until = now() + interval '100 years',
         updated_at = now()
   WHERE id = p_usuario;

  -- Las sesiones abiertas se cierran ahora y no cuando venzan.
  DELETE FROM auth.refresh_tokens WHERE user_id = p_usuario::text;
  DELETE FROM auth.sessions WHERE user_id = p_usuario;

  -- Lo que tenía pendiente para entrar o cambiar la clave deja de servir.
  UPDATE tokens_activacion_cuenta SET usado_en = now()
   WHERE usuario_id = p_usuario AND usado_en IS NULL;
  UPDATE tokens_recuperacion_clave SET usado_en = now()
   WHERE usuario_id = p_usuario AND usado_en IS NULL;
  UPDATE cambios_de_clave_habilitados SET anulado_en = now()
   WHERE usuario_id = p_usuario AND usado_en IS NULL AND anulado_en IS NULL;
  UPDATE codigos_al_telefono SET anulado_en = now()
   WHERE usuario_id = p_usuario AND verificado_en IS NULL AND anulado_en IS NULL;
  UPDATE equipos_conocidos SET revocado_en = now()
   WHERE usuario_id = p_usuario AND revocado_en IS NULL;

  -- La responsabilidad del reclutamiento queda libre, como quedaba al borrar la cuenta.
  UPDATE configuracion_reclutamiento SET responsable_id = NULL
   WHERE responsable_id = p_usuario AND prestadora_id = v_prestadora;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."desactivar_la_cuenta"("p_usuario" "uuid", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."deshacer_el_alta_de_la_cuenta"("p_usuario" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid;
BEGIN
  -- Único borrado de una cuenta: deshace un alta que se cortó, y sólo si la cuenta nunca entró.
  IF auth.jwt() ->> 'role' IS DISTINCT FROM 'trabajo_sin_persona' THEN RETURN false; END IF;
  v_prestadora := interno.prestadora_actual();
  IF v_prestadora IS NULL OR p_usuario IS NULL THEN RETURN false; END IF;

  IF EXISTS (SELECT 1 FROM auth.users WHERE id = p_usuario AND last_sign_in_at IS NOT NULL) THEN
    RETURN false;
  END IF;

  DELETE FROM usuarios
   WHERE id = p_usuario
     AND prestadora_id = v_prestadora
     AND rol IN ('coordinador', 'asistente', 'cliente')
     AND desactivada_en IS NULL;
  IF NOT FOUND THEN RETURN false; END IF;

  DELETE FROM auth.users WHERE id = p_usuario;
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."deshacer_el_alta_de_la_cuenta"("p_usuario" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."documento_autorizacion_signos_vitales"("p_paciente" "uuid", "p_idioma" "text") RETURNS TABLE("titulo" "text", "texto" "text", "verificador" "text", "idioma" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid;
BEGIN
  SELECT pa.prestadora_id INTO v_prestadora FROM pacientes pa WHERE pa.id = p_paciente;
  IF v_prestadora IS NULL OR v_prestadora <> interno.prestadora_actual() THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  IF auth.jwt() ->> 'role' IS DISTINCT FROM 'trabajo_sin_persona'
     AND NOT (interno.es_personal_de_la_prestadora() AND interno.alcanza_la_informacion_de_salud(p_paciente))
     AND NOT (p_paciente IN (SELECT interno.pacientes_del_cliente())
              AND interno.persona_autorizada_puede(auth.uid(), 'persona_autorizada_ficha_del_paciente')) THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT * FROM interno.documento_autorizacion_signos_vitales(p_paciente, p_idioma);
END;
$$;


ALTER FUNCTION "public"."documento_autorizacion_signos_vitales"("p_paciente" "uuid", "p_idioma" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."domicilio_del_paciente_en"("p_paciente_id" "uuid", "p_fecha" "date") RETURNS TABLE("paciente_id" "uuid", "domicilio_temporal_id" "uuid", "calle" "text", "numero" "text", "piso" "text", "unidad" "text", "lugar" "text", "lat" double precision, "lng" double precision, "es_temporal" boolean, "motivo" "text", "desde" "date", "hasta" "date")
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select * from public.domicilios_de_pacientes_en(array[p_paciente_id], p_fecha);
$$;


ALTER FUNCTION "public"."domicilio_del_paciente_en"("p_paciente_id" "uuid", "p_fecha" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."domicilios_de_pacientes_en"("p_pacientes" "uuid"[], "p_fecha" "date") RETURNS TABLE("paciente_id" "uuid", "domicilio_temporal_id" "uuid", "calle" "text", "numero" "text", "piso" "text", "unidad" "text", "lugar" "text", "lat" double precision, "lng" double precision, "es_temporal" boolean, "motivo" "text", "desde" "date", "hasta" "date")
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select
    p.id as paciente_id,
    d.id as domicilio_temporal_id,
    case when d.id is null then f.calle else d.calle end as calle,
    case when d.id is null then f.numero else d.numero end as numero,
    case when d.id is null then f.piso else d.piso end as piso,
    case when d.id is null then f.unidad else d.unidad end as unidad,
    l.nombre as lugar,
    case when d.id is null then f.lat else d.lat end as lat,
    case when d.id is null then f.lng else d.lng end as lng,
    d.id is not null as es_temporal,
    d.motivo,
    d.fecha_inicio as desde,
    d.fecha_fin as hasta
  from public.pacientes p
  join public.personas f on f.id = p.persona_id and f.prestadora_id = p.prestadora_id
  left join lateral (
    select t.id, t.calle, t.numero, t.piso, t.unidad, t.lugar_id, t.lat, t.lng, t.motivo,
           t.fecha_inicio, t.fecha_fin
      from public.domicilios_temporales_paciente t
     where t.paciente_id = p.id
       and t.fecha_inicio <= p_fecha
       and (t.fecha_fin is null or t.fecha_fin >= p_fecha)
     -- La restricción de la tabla garantiza que haya una sola; el orden y el tope son la red por
     -- si alguna vez se afloja.
     order by t.fecha_inicio desc
     limit 1
  ) d on true
  left join public.lugares l
    on l.id = case when d.id is null then f.lugar_id else d.lugar_id end
   and l.prestadora_id = p.prestadora_id
  where p.id = any (p_pacientes);
$$;


ALTER FUNCTION "public"."domicilios_de_pacientes_en"("p_pacientes" "uuid"[], "p_fecha" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."el_mensaje_se_guarda_ya_tapado"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  lo_tapado record;
BEGIN
  -- Un mensaje automático no lo escribió nadie: su cuerpo es una clave de traducción. Buscarle
  -- un teléfono a una clave no encuentra nada y podría romperla.
  IF NEW.automatico THEN
    NEW.regla_tapada := NULL;
    RETURN NEW;
  END IF;

  SELECT t.texto, t.regla
    INTO lo_tapado
    FROM interno.tapar_lo_que_no_viaja_en_un_mensaje(NEW.cuerpo, NEW.prestadora_id) t;

  NEW.cuerpo       := lo_tapado.texto;
  NEW.regla_tapada := lo_tapado.regla;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."el_mensaje_se_guarda_ya_tapado"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."el_mensaje_se_guarda_ya_tapado"() IS 'Sobre mensajes_match: tapa el texto antes de escribirlo y anota que regla lo tapo. El texto tapado no se guarda, no se registra y no sale en ningun error.';



CREATE OR REPLACE FUNCTION "public"."estado_de_factura"("p_monto_total" numeric, "p_cobrado" numeric, "p_fecha_vencimiento" "date") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    -- Nada por cobrar, nada que reclamar. Vale también para una factura de cero.
    WHEN COALESCE(p_cobrado, 0) >= COALESCE(p_monto_total, 0) THEN 'pagada'
    WHEN p_fecha_vencimiento IS NOT NULL AND p_fecha_vencimiento < CURRENT_DATE THEN 'vencida'
    ELSE 'pendiente'
  END;
$$;


ALTER FUNCTION "public"."estado_de_factura"("p_monto_total" numeric, "p_cobrado" numeric, "p_fecha_vencimiento" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."estado_de_factura"("p_monto_total" numeric, "p_cobrado" numeric, "p_fecha_vencimiento" "date") IS 'Único lugar donde se decide si una factura está pagada, vencida o pendiente. Cobro parcial: sigue pendiente (o vencida), y el cuánto falta lo dice el saldo.';



CREATE OR REPLACE FUNCTION "public"."exigir_paciente_del_turno"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM guardia_pacientes gp
    WHERE gp.guardia_id = NEW.guardia_id AND gp.paciente_id = NEW.paciente_id
  ) THEN
    RAISE EXCEPTION 'El reporte habla de un Paciente que este turno no atiende';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."exigir_paciente_del_turno"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auditoria_de_acceso_mutacion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_registro_id UUID;
BEGIN
  IF NOT hay_permiso_de_acceso_vigente() THEN
    RETURN NULL;
  END IF;

  IF TG_OP = 'DELETE' THEN
    BEGIN
      v_registro_id := OLD.id;
    EXCEPTION WHEN undefined_column THEN
      v_registro_id := NULL;
    END;
  ELSE
    BEGIN
      v_registro_id := NEW.id;
    EXCEPTION WHEN undefined_column THEN
      v_registro_id := NULL;
    END;
  END IF;

  INSERT INTO auditoria_de_accesos (admin_id, prestadora_id, tipo_evento, tabla_afectada, operacion, registro_id)
  VALUES (auth.uid(), prestadora_actual(), 'mutacion', TG_TABLE_NAME, TG_OP, v_registro_id);

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_auditoria_de_acceso_mutacion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_completar_moneda"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
BEGIN
  IF NEW.moneda IS NULL AND NEW.prestadora_id IS NOT NULL THEN
    NEW.moneda := interno.moneda_de_prestadora(NEW.prestadora_id);
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_completar_moneda"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_completar_moneda_desde_cliente"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
BEGIN
  IF NEW.moneda IS NULL THEN
    SELECT interno.moneda_de_prestadora(f.prestadora_id) INTO NEW.moneda
    FROM public.clientes f WHERE f.id = NEW.cliente_id;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_completar_moneda_desde_cliente"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_completar_moneda_desde_padre"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  tabla_padre text := TG_ARGV[0];
  columna_fk  text := TG_ARGV[1];
  moneda_padre public.moneda_iso;
BEGIN
  IF NEW.moneda IS NULL THEN
    EXECUTE format('SELECT moneda FROM public.%I WHERE id = ($1).%I', tabla_padre, columna_fk)
      INTO moneda_padre
      USING NEW;
    NEW.moneda := moneda_padre;
  END IF;
  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."fn_completar_moneda_desde_padre"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_completar_prestadora_desde_padre"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  tabla_padre text := TG_ARGV[0];
  columna_fk  text := TG_ARGV[1];
  prestadora_padre uuid;
BEGIN
  IF NEW.prestadora_id IS NULL THEN
    EXECUTE format('SELECT prestadora_id FROM public.%I WHERE id = ($1).%I', tabla_padre, columna_fk)
      INTO prestadora_padre
      USING NEW;
    NEW.prestadora_id := prestadora_padre;
  END IF;
  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."fn_completar_prestadora_desde_padre"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_completar_prestadora_desde_padre"() IS 'Completa la Prestadora de una fila hija tomándola de su fila padre. Recibe el nombre de la tabla padre y el de la columna que la apunta.';



CREATE OR REPLACE FUNCTION "public"."fn_estado_factura_segun_cobros"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_cobrado numeric;
BEGIN
  SELECT cobrado INTO v_cobrado FROM public.resumen_cobros_de_factura(NEW.id);
  NEW.estado := public.estado_de_factura(
    public.monto_a_cobrar_de_factura(NEW.monto_total, NEW.monto_facturado, NEW.id),
    v_cobrado,
    NEW.fecha_vencimiento
  );
  RETURN NEW;
END;
$$;


