    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT COALESCE(public.tiene_permiso_de(interno.usuario_de_la_sesion(), p_accion), false);
$$;


