);


ALTER TABLE "public"."agrupaciones_tipos_asistente" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."alarmas_tomadas" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "tipo" "text" NOT NULL,
    "referencia_id" "uuid" NOT NULL,
    "tomada_por" "uuid" NOT NULL,
    "tomada_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "vence_at" timestamp with time zone NOT NULL,
    "soltada_at" timestamp with time zone,
    "nota" "text",
    CONSTRAINT "alarmas_tomadas_tipo_conocido" CHECK (("tipo" = ANY (ARRAY['alerta_temprana_guardia'::"text", 'incidente_relevo'::"text", 'guardia_sin_cerrar'::"text", 'incidente_turno_sin_cubrir'::"text", 'emergencia_guardia'::"text"]))),
    CONSTRAINT "alarmas_tomadas_vence_despues_de_tomarse" CHECK (("vence_at" > "tomada_at"))
);


ALTER TABLE "public"."alarmas_tomadas" OWNER TO "postgres";


COMMENT ON TABLE "public"."alarmas_tomadas" IS 'Quien se hizo cargo de una alarma y hasta cuando. Mientras la toma esta en pie el proceso de fondo no insiste con esa alarma. Tomarla no la resuelve.';



COMMENT ON COLUMN "public"."alarmas_tomadas"."referencia_id" IS 'La fila alarmada. La tabla a la que apunta depende del tipo: no hay clave foranea posible.';



COMMENT ON COLUMN "public"."alarmas_tomadas"."vence_at" IS 'Cuando vuelve la alarma si el problema sigue abierto. Cuanto dura la toma lo decide cada Prestadora; el valor de fabrica vive en panel/src/lib/alarmasTomadas.js.';



COMMENT ON COLUMN "public"."alarmas_tomadas"."nota" IS 'Lo que quien la tomo dejo escrito. Nunca datos de salud ni de la persona atendida.';



CREATE OR REPLACE VIEW "public"."alarmas_tomadas_quien_la_tomo" WITH ("security_invoker"='true') AS
 SELECT "id",
    "prestadora_id",
    "tipo",
    "referencia_id",
    "tomada_por",
    "tomada_at",
    "vence_at",
    "soltada_at",
    "nota",
    "interno"."nombre_de_usuario"("tomada_por") AS "tomada_por_nombre"
   FROM "public"."alarmas_tomadas" "a";


ALTER VIEW "public"."alarmas_tomadas_quien_la_tomo" OWNER TO "postgres";


COMMENT ON VIEW "public"."alarmas_tomadas_quien_la_tomo" IS 'Las tomas de alarma con el nombre de quien la tomo ya resuelto. Muestra exactamente las mismas filas que alarmas_tomadas: lo unico que agrega es el nombre. Para escribir se usa la tabla.';



