    "conversacion_id" "uuid",
    "mensaje_entrante_id" "uuid",
    "mensaje_saliente_id" "uuid",
    "respuesta_preparada_id" "uuid",
    "resultado" "text" NOT NULL,
    "motivo" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "el_motivo_sale_de_la_lista" CHECK (("motivo" = ANY (ARRAY['respuesta_aprobada'::"text", 'sin_respuesta_aprobada'::"text", 'tema_de_salud'::"text", 'emergencia'::"text", 'sin_telefono_de_emergencia'::"text", 'no_se_pudo_clasificar'::"text", 'envio_fallido'::"text", 'pidio_una_persona'::"text", 'la_atiende_una_persona'::"text"]))),
    CONSTRAINT "el_resultado_sale_de_la_lista" CHECK (("resultado" = ANY (ARRAY['respondida'::"text", 'derivada_a_una_persona'::"text", 'emergencia_avisada'::"text"]))),
    CONSTRAINT "lo_respondido_dice_con_que_respuesta" CHECK ((("resultado" <> 'respondida'::"text") OR ("respuesta_preparada_id" IS NOT NULL)))
);


ALTER TABLE "public"."auditoria_respuesta_automatica_whatsapp" OWNER TO "postgres";


