    "expira_en" timestamp with time zone NOT NULL,
    "usado_en" timestamp with time zone,
    "anulado_en" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "cambios_de_clave_habilitados_no_a_uno_mismo" CHECK (("usuario_id" <> "habilitado_por"))
);


ALTER TABLE "public"."cambios_de_clave_habilitados" OWNER TO "postgres";


COMMENT ON TABLE "public"."cambios_de_clave_habilitados" IS 'La puerta que la Prestadora le abre a alguien que llamó porque no puede entrar. Dura poco, sirve una vez, y no guarda ninguna clave ni nada con que deducirla: quien habilita nunca elige ni ve la clave de nadie.';



CREATE TABLE IF NOT EXISTS "public"."cargas_sujetas_a_aprobacion" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "paciente_id" "uuid" NOT NULL,
    "tabla" "text" NOT NULL,
    "operacion" "text" NOT NULL,
    "registro_id" "uuid",
    "datos" "jsonb" NOT NULL,
    "cargado_por" "uuid" NOT NULL,
    "cargado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "estado" "text" DEFAULT 'pendiente'::"text" NOT NULL,
    "motivo_rechazo" "text",
    "revisado_por" "uuid",
    "revisado_en" timestamp with time zone,
    CONSTRAINT "cargas_sujetas_a_aprobacion_estado_check" CHECK (("estado" = ANY (ARRAY['pendiente'::"text", 'aceptada'::"text", 'rechazada'::"text"]))),
    CONSTRAINT "cargas_sujetas_a_aprobacion_operacion_check" CHECK (("operacion" = ANY (ARRAY['alta'::"text", 'modificacion'::"text"]))),
    CONSTRAINT "cargas_sujetas_a_aprobacion_tabla_check" CHECK (("tabla" = ANY (ARRAY['informacion_de_salud_del_paciente'::"text", 'domicilios_temporales_paciente'::"text"]))),
    CONSTRAINT "el_rechazo_lleva_motivo" CHECK ((("estado" <> 'rechazada'::"text") OR (NULLIF("btrim"("motivo_rechazo"), ''::"text") IS NOT NULL))),
    CONSTRAINT "la_modificacion_de_un_domicilio_dice_cual" CHECK ((("tabla" <> 'domicilios_temporales_paciente'::"text") OR ("operacion" = 'alta'::"text") OR ("registro_id" IS NOT NULL))),
    CONSTRAINT "la_revision_dice_quien_y_cuando" CHECK ((("estado" = 'pendiente'::"text") = (("revisado_por" IS NULL) AND ("revisado_en" IS NULL))))
);


ALTER TABLE "public"."cargas_sujetas_a_aprobacion" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."catalogo_acciones_permisos" (
    "accion" "text" NOT NULL,
    "default_solo_admin" boolean NOT NULL,
    "orden" smallint NOT NULL,
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."catalogo_acciones_permisos" OWNER TO "postgres";


COMMENT ON TABLE "public"."catalogo_acciones_permisos" IS 'Las acciones que una Prestadora puede reservar al administrador, y qué pasa cuando no configuró nada. Punto único de verdad del valor por defecto (pendiente #127).';



CREATE TABLE IF NOT EXISTS "public"."catalogo_acciones_registradas" (
    "accion" "text" NOT NULL,
    "grupo" "text" NOT NULL,
    "orden" smallint NOT NULL,
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "la_hace_el_sistema" boolean DEFAULT false NOT NULL,
    CONSTRAINT "catalogo_acciones_registradas_grupo_conocido" CHECK (("grupo" = ANY (ARRAY['entrada_administrativa'::"text", 'permisos_y_membresia'::"text", 'borrado_de_datos'::"text", 'modificacion_critica'::"text", 'consecuencia_economica'::"text"])))
);


ALTER TABLE "public"."catalogo_acciones_registradas" OWNER TO "postgres";


COMMENT ON TABLE "public"."catalogo_acciones_registradas" IS 'Que acciones deja anotadas el registro de actividad. La clave es opaca: el texto visible vive en las traducciones del Panel, en los tres idiomas.';



COMMENT ON COLUMN "public"."catalogo_acciones_registradas"."grupo" IS 'A cual de los cinco casos que pide la regla de la empresa responde esta accion.';



CREATE TABLE IF NOT EXISTS "public"."catalogo_datos_del_registro" (
    "clave" "text" NOT NULL,
    "orden" smallint NOT NULL,
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."catalogo_datos_del_registro" OWNER TO "postgres";


COMMENT ON TABLE "public"."catalogo_datos_del_registro" IS 'Los unicos datos con nombre que el registro de actividad admite adentro de `detalle`. Lista de lo permitido, no de lo prohibido: lo que no figura acá hace fallar la escritura.';



CREATE TABLE IF NOT EXISTS "public"."catalogo_documentos_de_identidad" (
    "pais" "text" NOT NULL,
    "clase" "text" NOT NULL,
    "codigo" "text" NOT NULL,
    "sigla" "text" NOT NULL,
    "orden" integer DEFAULT 100 NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "lleva_pais" boolean DEFAULT false NOT NULL,
    "verifica_modulo_11" boolean DEFAULT false NOT NULL,
    "contiene_dni" boolean DEFAULT false NOT NULL,
    CONSTRAINT "catalogo_documentos_clase_conocida" CHECK (("clase" = ANY (ARRAY['fisica'::"text", 'juridica'::"text"])))
);


ALTER TABLE "public"."catalogo_documentos_de_identidad" OWNER TO "postgres";


COMMENT ON TABLE "public"."catalogo_documentos_de_identidad" IS 'Que documentos de identidad emite cada pais, y a que clase de Persona le corresponde cada uno. No es configuracion de ninguna Prestadora: es lo que emite un Estado.';



CREATE TABLE IF NOT EXISTS "public"."catalogo_funciones_intermediacion" (
    "clave" "text" NOT NULL,
    "orden" smallint NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."catalogo_funciones_intermediacion" OWNER TO "postgres";


COMMENT ON TABLE "public"."catalogo_funciones_intermediacion" IS 'Las funciones de la modalidad Match que tienen riesgo legal conocido. Es el catálogo de la plataforma: qué se puede encender. Si esa función tiene advertencia escrita para la jurisdicción de la Prestadora, encenderla la muestra y la deja auditada.';



COMMENT ON COLUMN "public"."catalogo_funciones_intermediacion"."clave" IS 'La misma cadena que nombra a esta función en advertencias_legales y en auditoria_advertencias_legales. Nombre guardado: no se renombra.';



COMMENT ON COLUMN "public"."catalogo_funciones_intermediacion"."orden" IS 'En qué orden se listan en pantalla. Es el orden del documento legal, para poder leerlas al lado del documento.';



CREATE TABLE IF NOT EXISTS "public"."catalogo_generos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "pais" "text" NOT NULL,
    "codigo" "text" NOT NULL,
    "orden" integer NOT NULL,
    "activo" boolean DEFAULT true NOT NULL
);


ALTER TABLE "public"."catalogo_generos" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."catalogo_identificadores_de_cuenta" (
    "pais" "text" NOT NULL,
    "codigo" "text" NOT NULL,
    "sigla" "text" NOT NULL,
    "orden" integer DEFAULT 100 NOT NULL,
    "activo" boolean DEFAULT true NOT NULL
);


ALTER TABLE "public"."catalogo_identificadores_de_cuenta" OWNER TO "postgres";


COMMENT ON TABLE "public"."catalogo_identificadores_de_cuenta" IS 'Con que numero se identifica una cuenta bancaria en cada pais. Un pais nuevo entra cargando filas, nunca tocando codigo.';



COMMENT ON COLUMN "public"."catalogo_identificadores_de_cuenta"."sigla" IS 'Como se llama ese identificador en su pais. No se traduce: CBU y CVU son nombres propios.';



CREATE TABLE IF NOT EXISTS "public"."catalogo_paises" (
    "codigo" "text" NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "catalogo_paises_codigo_check" CHECK (("codigo" ~ '^[A-Z]{2}$'::"text"))
);


ALTER TABLE "public"."catalogo_paises" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."catalogo_periodos_cobro" (
    "clave" "text" NOT NULL,
    "orden" smallint NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."catalogo_periodos_cobro" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."catalogo_prefijos_de_celular" (
    "pais" "text" NOT NULL,
    "prefijo" "text" NOT NULL,
    "orden" integer DEFAULT 100 NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    CONSTRAINT "el_prefijo_de_celular_es_solo_digitos" CHECK (("prefijo" ~ '^[0-9]+$'::"text"))
);


ALTER TABLE "public"."catalogo_prefijos_de_celular" OWNER TO "postgres";


COMMENT ON TABLE "public"."catalogo_prefijos_de_celular" IS 'Con que empieza un numero de celular en cada pais, en forma internacional y solo con digitos. Un pais nuevo entra cargando filas, nunca tocando codigo. El pais sin filas no tiene ningun numero reconocido como celular.';



COMMENT ON COLUMN "public"."catalogo_prefijos_de_celular"."prefijo" IS 'Digitos con los que empieza el numero, sin el mas y sin separadores. Incluye el codigo de pais.';



CREATE TABLE IF NOT EXISTS "public"."catalogo_proveedores_de_mensaje_de_texto" (
    "proveedor" "text" NOT NULL,
    "orden" smallint DEFAULT 100 NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."catalogo_proveedores_de_mensaje_de_texto" OWNER TO "postgres";


COMMENT ON TABLE "public"."catalogo_proveedores_de_mensaje_de_texto" IS 'Los proveedores de mensaje de texto que el producto conoce. Nace vacio a proposito: con este catalogo vacio la via sale en la lista de Avisos y no se puede elegir. Un proveedor entra cargando una fila, nunca tocando codigo.';



COMMENT ON COLUMN "public"."catalogo_proveedores_de_mensaje_de_texto"."proveedor" IS 'Como se llama el proveedor. Es un nombre propio y no se traduce.';



CREATE TABLE IF NOT EXISTS "public"."catalogo_software_externo" (
    "clave" "text" NOT NULL,
    "clase" "text" NOT NULL,
    "nombre" "text" NOT NULL,
    "orden" smallint DEFAULT 0 NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "catalogo_software_externo_clase_check" CHECK (("clase" = ANY (ARRAY['facturacion'::"text", 'creditos_y_cobranzas'::"text"]))),
    CONSTRAINT "catalogo_software_externo_nombre_check" CHECK (("length"("btrim"("nombre")) > 0))
);


ALTER TABLE "public"."catalogo_software_externo" OWNER TO "postgres";


COMMENT ON TABLE "public"."catalogo_software_externo" IS 'Con que software de afuera se puede conectar una Prestadora: los de facturacion y los de creditos y cobranzas. Ninguna de las dos tareas se hace aca; esto dice unicamente con quien se habla.';



COMMENT ON COLUMN "public"."catalogo_software_externo"."clase" IS 'Para que sirve ese software: facturacion, o creditos_y_cobranzas.';



COMMENT ON COLUMN "public"."catalogo_software_externo"."nombre" IS 'El nombre comercial del producto de ese tercero. No se traduce: es una marca.';



CREATE TABLE IF NOT EXISTS "public"."catalogo_usos_del_codigo_al_telefono" (
    "uso" "text" NOT NULL,
    "orden" smallint NOT NULL,
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."catalogo_usos_del_codigo_al_telefono" OWNER TO "postgres";


COMMENT ON TABLE "public"."catalogo_usos_del_codigo_al_telefono" IS 'Para qué se manda un código al teléfono. Son tres y ninguna Prestadora las cambia: verificar el número, entrar desde un equipo nuevo y recuperar la clave.';



CREATE TABLE IF NOT EXISTS "public"."certificados" (
