    "sentido" "text" NOT NULL,
    "monto" numeric(12,2) NOT NULL,
    "comprobante_tipo" "text" NOT NULL,
    "comprobante_numero" "text",
    "motivo" "text" NOT NULL,
    "fecha" "date" DEFAULT CURRENT_DATE NOT NULL,
    "registrada_por" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "moneda" "public"."moneda_iso",
    CONSTRAINT "correcciones_factura_cliente_comprobante_tipo_check" CHECK (("length"("btrim"("comprobante_tipo")) > 0)),
    CONSTRAINT "correcciones_factura_cliente_monto_check" CHECK (("monto" > (0)::numeric)),
    CONSTRAINT "correcciones_factura_cliente_motivo_check" CHECK (("length"("btrim"("motivo")) > 0)),
