    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "especialidades_nombre_check" CHECK (("length"("btrim"("nombre")) > 0)),
    CONSTRAINT "especialidades_tipo_matricula_check" CHECK ((("tipo_matricula" IS NULL) OR ("length"("btrim"("tipo_matricula")) > 0)))
);


ALTER TABLE "public"."especialidades" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."especialidades_asistente" (
    "prestadora_id" "uuid" NOT NULL,
    "asistente_id" "uuid" NOT NULL,
    "especialidad_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."especialidades_asistente" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."estados_de_cuenta_externos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "cliente_id" "uuid" NOT NULL,
    "saldo" numeric(14,2) NOT NULL,
    "moneda" "text" NOT NULL,
    "atrasado" boolean NOT NULL,
    "dias_de_atraso" integer,
    "vencimiento_mas_antiguo" "date",
    "fecha_del_estado" "date",
    "numero_del_aviso" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "estados_de_cuenta_externos_atraso_no_negativo" CHECK ((("dias_de_atraso" IS NULL) OR ("dias_de_atraso" >= 0))),
    CONSTRAINT "estados_de_cuenta_externos_moneda_con_forma" CHECK (("moneda" ~ '^[A-Z]{3}$'::"text"))
);


ALTER TABLE "public"."estados_de_cuenta_externos" OWNER TO "postgres";


COMMENT ON TABLE "public"."estados_de_cuenta_externos" IS 'Lo que el software de creditos y cobranzas de la Prestadora informo sobre la cuenta de un Cliente. Informacion, no decision: nada se corta ni se bloquea por esto, y este sistema no lo recalcula.';



COMMENT ON COLUMN "public"."estados_de_cuenta_externos"."saldo" IS 'Cuanto debe ese Cliente segun quien lleva la cobranza. Negativo es saldo a favor. No se calcula aca: se guarda tal como llego.';



COMMENT ON COLUMN "public"."estados_de_cuenta_externos"."moneda" IS 'En que moneda esta el saldo, en codigo de tres letras. Todo importe viaja con su moneda.';



COMMENT ON COLUMN "public"."estados_de_cuenta_externos"."atrasado" IS 'Si quien lleva la cobranza considera que ese Cliente esta atrasado. Lo decide el, no este sistema.';



COMMENT ON COLUMN "public"."estados_de_cuenta_externos"."dias_de_atraso" IS 'Cuantos dias de atraso informo quien avisa. Vacio cuando no lo informa: no se deduce de ninguna fecha.';



COMMENT ON COLUMN "public"."estados_de_cuenta_externos"."vencimiento_mas_antiguo" IS 'La fecha de vencimiento mas vieja que sigue impaga, si quien avisa la informa.';



COMMENT ON COLUMN "public"."estados_de_cuenta_externos"."fecha_del_estado" IS 'A que dia corresponde esta foto de la cuenta. Es de quien avisa, no de cuando entro el aviso.';



COMMENT ON COLUMN "public"."estados_de_cuenta_externos"."numero_del_aviso" IS 'Como numero el aviso quien lo mando. Sirve para no atender dos veces el mismo.';



CREATE OR REPLACE VIEW "public"."estado_de_cuenta_externo_vigente" WITH ("security_invoker"='true') AS
 SELECT DISTINCT ON ("cliente_id") "cliente_id",
    "prestadora_id",
    "saldo",
    "moneda",
    "atrasado",
    "dias_de_atraso",
    "vencimiento_mas_antiguo",
    "fecha_del_estado",
    "numero_del_aviso",
    "created_at" AS "informado_at"
   FROM "public"."estados_de_cuenta_externos" "e"
  ORDER BY "cliente_id", "created_at" DESC;


ALTER VIEW "public"."estado_de_cuenta_externo_vigente" OWNER TO "postgres";


COMMENT ON VIEW "public"."estado_de_cuenta_externo_vigente" IS 'El ultimo estado de cuenta informado de cada Cliente, que es el que rige. Los anteriores quedan guardados en estados_de_cuenta_externos.';



CREATE TABLE IF NOT EXISTS "public"."etapas_incorporacion_asistente" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "clave" "text" NOT NULL,
    "nombre" "text" NOT NULL,
    "orden" smallint NOT NULL,
    "activa" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"()
);


ALTER TABLE "public"."etapas_incorporacion_asistente" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."excepciones_familiar_relevo" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "incidente_id" "uuid",
    "registrado_por" "uuid" NOT NULL,
    "motivo" "text",
    "desde_at" timestamp with time zone NOT NULL,
    "hasta_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "guardia_id" "uuid" NOT NULL,
    "origen" "text" NOT NULL,
    "familiar_persona_id" "uuid",
    CONSTRAINT "excepciones_familiar_relevo_origen_conocido" CHECK (("origen" = ANY (ARRAY['relevo'::"text", 'turno_sin_cubrir'::"text", 'extension'::"text"]))),
    CONSTRAINT "excepciones_familiar_relevo_termina_despues" CHECK ((("hasta_at" IS NULL) OR ("hasta_at" >= "desde_at")))
);


ALTER TABLE "public"."excepciones_familiar_relevo" OWNER TO "postgres";


COMMENT ON TABLE "public"."excepciones_familiar_relevo" IS 'Un familiar termino cuidando porque la Prestadora no mando a nadie. Es un defecto grave del servicio que no se pudo solucionar, nunca un turno cubierto: no cierra la guardia ni la cuenta como prestada.';



COMMENT ON COLUMN "public"."excepciones_familiar_relevo"."registrado_por" IS 'Quien de la Prestadora dejo escrito el hecho. No lo autorizo: a un familiar no se le pide que se quede.';



COMMENT ON COLUMN "public"."excepciones_familiar_relevo"."hasta_at" IS 'Cuando volvio a haber personal en esa casa. Vacio mientras siga sin haberlo.';



COMMENT ON COLUMN "public"."excepciones_familiar_relevo"."origen" IS 'Por cual de los tres caminos el turno quedo sin nadie: relevo, turno_sin_cubrir o extension.';



COMMENT ON COLUMN "public"."excepciones_familiar_relevo"."familiar_persona_id" IS 'Cual Legajo del Padron es el familiar que se quedo cubriendo. Es siempre una Persona fisica. Admite vacio solo por las filas que ya estaban cargadas: en el alta lo exige el disparador.';



CREATE TABLE IF NOT EXISTS "public"."excepciones_por_documentos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "guardia_id" "uuid" NOT NULL,
    "asistente_id" "uuid" NOT NULL,
    "usuario_id" "uuid" NOT NULL,
    "motivo" "text" NOT NULL,
    "documentos" "text"[] NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "excepciones_por_documentos_motivo_check" CHECK (("btrim"("motivo") <> ''::"text"))
);


ALTER TABLE "public"."excepciones_por_documentos" OWNER TO "postgres";


COMMENT ON TABLE "public"."excepciones_por_documentos" IS 'Turnos de guardia asignados con documentos pendientes: quién, a quién, por qué y qué documentos faltaban. Vale sólo para esa guardia y ese Asistente. No se borra.';



CREATE TABLE IF NOT EXISTS "public"."extensiones_de_turno" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "guardia_id" "uuid" NOT NULL,
    "relevo_guardia_id" "uuid",
    "desde_at" timestamp with time zone NOT NULL,
    "hasta_at" timestamp with time zone,
    "ultima_notificacion_at" timestamp with time zone,
    "veces_notificado" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "extensiones_de_turno_termina_despues" CHECK ((("hasta_at" IS NULL) OR ("hasta_at" >= "desde_at")))
);


ALTER TABLE "public"."extensiones_de_turno" OWNER TO "postgres";


COMMENT ON TABLE "public"."extensiones_de_turno" IS 'El rato que una Asistente se queda adentro despues de que termino su turno porque el relevo no llego. Se abre sola y se cierra cuando llega el relevo o cuando ella cierra el turno. De aca salen las horas de mas.';



COMMENT ON COLUMN "public"."extensiones_de_turno"."desde_at" IS 'La hora de fin de su propio turno, no cuando el sistema se dio cuenta.';



CREATE TABLE IF NOT EXISTS "public"."facturas_cliente" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "cliente_id" "uuid" NOT NULL,
    "periodo" "date" NOT NULL,
    "monto_total" numeric(12,2) DEFAULT 0 NOT NULL,
    "estado" "text" DEFAULT 'pendiente'::"text" NOT NULL,
    "fecha_emision" "date" DEFAULT CURRENT_DATE NOT NULL,
    "fecha_vencimiento" "date",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "moneda" "public"."moneda_iso" NOT NULL,
    "monto_facturado" numeric(12,2),
    "comprobante_tipo" "text",
    "comprobante_numero" "text",
    "facturado_at" timestamp with time zone,
    "comprobante_archivo" "text",
    "comprobante_subido_at" timestamp with time zone,
    "servicio_id" "uuid" NOT NULL,
    CONSTRAINT "facturas_cliente_estado_check" CHECK (("estado" = ANY (ARRAY['pendiente'::"text", 'pagada'::"text", 'vencida'::"text"]))),
    CONSTRAINT "facturas_cliente_monto_facturado_check" CHECK ((("monto_facturado" IS NULL) OR ("monto_facturado" >= (0)::numeric)))
);


ALTER TABLE "public"."facturas_cliente" OWNER TO "postgres";


COMMENT ON COLUMN "public"."facturas_cliente"."monto_total" IS 'Lo que el sistema calculo sumando los renglones: lo que se manda a facturar. No incluye impuestos.';



COMMENT ON COLUMN "public"."facturas_cliente"."monto_facturado" IS 'Lo que el software de facturacion informo que emitio, con impuestos adentro. Vacio mientras no se haya facturado. Es contra este monto que se mide la cobranza.';



COMMENT ON COLUMN "public"."facturas_cliente"."comprobante_tipo" IS 'Como llama el software de facturacion al comprobante que emitio. Texto que se guarda y no se interpreta: cada pais tiene los suyos y el sistema no conoce ninguno.';



COMMENT ON COLUMN "public"."facturas_cliente"."comprobante_numero" IS 'El numero del comprobante emitido, tal como lo devolvio el software de facturacion.';



COMMENT ON COLUMN "public"."facturas_cliente"."facturado_at" IS 'Cuando se anoto lo que emitio el software de facturacion. Vacio mientras no se haya facturado.';



CREATE TABLE IF NOT EXISTS "public"."facturas_cliente_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "factura_id" "uuid" NOT NULL,
    "paciente_id" "uuid",
    "descripcion" "text" NOT NULL,
    "monto" numeric(12,2) NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "servicio_id" "uuid",
    "moneda" "public"."moneda_iso" NOT NULL,
    "prestadora_id" "uuid" NOT NULL
);


ALTER TABLE "public"."facturas_cliente_items" OWNER TO "postgres";


COMMENT ON COLUMN "public"."facturas_cliente_items"."prestadora_id" IS 'La Prestadora dueña del renglón. Sale de la factura y no puede diferir de ella.';



CREATE TABLE IF NOT EXISTS "public"."finales_turno_sin_cubrir" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "clave" "text",
    "nombre" "text",
    "es_defecto_grave" boolean DEFAULT false NOT NULL,
    "pide_detalle" boolean DEFAULT false NOT NULL,
    "lo_escribe_el_sistema" boolean DEFAULT false NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "orden" integer DEFAULT 100 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "finales_turno_sin_cubrir_los_del_sistema_no_se_apagan" CHECK (((NOT "lo_escribe_el_sistema") OR "activo")),
    CONSTRAINT "finales_turno_sin_cubrir_los_del_sistema_son_del_producto" CHECK (((NOT "lo_escribe_el_sistema") OR ("clave" IS NOT NULL))),
    CONSTRAINT "finales_turno_sin_cubrir_nombre_segun_nivel" CHECK (((("clave" IS NOT NULL) AND ("nombre" IS NULL)) OR (("clave" IS NULL) AND ("nombre" IS NOT NULL))))
);


ALTER TABLE "public"."finales_turno_sin_cubrir" OWNER TO "postgres";


COMMENT ON TABLE "public"."finales_turno_sin_cubrir" IS 'Como puede terminar el expediente de un turno que quedo sin nadie. Cada Prestadora arma su lista: nace con los que trae el producto y a partir de ahi agrega y saca los que quiera.';



COMMENT ON COLUMN "public"."finales_turno_sin_cubrir"."clave" IS 'Final que trajo el producto. El texto visible sale de las traducciones, buscandolo por esta clave; es tambien lo que se guarda en el expediente.';



COMMENT ON COLUMN "public"."finales_turno_sin_cubrir"."nombre" IS 'Final que escribio la Prestadora. Se muestra tal cual, sin traducir, y es lo que se guarda en el expediente.';



COMMENT ON COLUMN "public"."finales_turno_sin_cubrir"."es_defecto_grave" IS 'Terminar asi deja escrito que el servicio fallo y no se pudo arreglar. Lo decide la Prestadora, porque solo ella sabe que es una falla en su forma de trabajar.';



COMMENT ON COLUMN "public"."finales_turno_sin_cubrir"."pide_detalle" IS 'Cerrar con este final obliga a escribir que se hizo.';



COMMENT ON COLUMN "public"."finales_turno_sin_cubrir"."lo_escribe_el_sistema" IS 'El final no se elige: lo escribe el motor cuando la base ya dice que el turno termino asi. No se ofrece para elegir y no se puede apagar.';



CREATE TABLE IF NOT EXISTS "public"."formas_de_cobro_intermediacion" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "nombre" "text" NOT NULL,
    "importe" numeric(12,2) NOT NULL,
    "moneda" "public"."moneda_iso" NOT NULL,
    "periodo_cantidad" integer,
    "periodo_unidad" "text",
    "dias_gratis" integer,
    "contactos_incluidos" integer,
    "renueva_sola" boolean DEFAULT false NOT NULL,
    "ofrecida" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "formas_cobro_intermediacion_contactos_positivos" CHECK ((("contactos_incluidos" IS NULL) OR ("contactos_incluidos" > 0))),
    CONSTRAINT "formas_cobro_intermediacion_dias_gratis_no_negativos" CHECK ((("dias_gratis" IS NULL) OR ("dias_gratis" >= 0))),
    CONSTRAINT "formas_cobro_intermediacion_importe_no_negativo" CHECK (("importe" >= (0)::numeric)),
    CONSTRAINT "formas_cobro_intermediacion_periodo_entero" CHECK ((("periodo_cantidad" IS NULL) = ("periodo_unidad" IS NULL))),
    CONSTRAINT "formas_cobro_intermediacion_periodo_positivo" CHECK ((("periodo_cantidad" IS NULL) OR ("periodo_cantidad" > 0))),
    CONSTRAINT "formas_cobro_intermediacion_renueva_con_periodo" CHECK ((("renueva_sola" = false) OR ("periodo_cantidad" IS NOT NULL)))
);


ALTER TABLE "public"."formas_de_cobro_intermediacion" OWNER TO "postgres";


COMMENT ON TABLE "public"."formas_de_cobro_intermediacion" IS 'Cómo cobra cada Prestadora el acceso a los datos de contacto. Las piezas, no los tipos: la forma sale de cómo se combinen. docs/PRD_07_Modalidad_Match.md §3.';



CREATE TABLE IF NOT EXISTS "public"."formulario_campos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "seccion_id" "uuid" NOT NULL,
    "prestadora_id" "uuid",
    "clave" "text" NOT NULL,
    "tipo" "text" NOT NULL,
    "etiqueta" "jsonb" NOT NULL,
    "obligatorio" boolean DEFAULT false NOT NULL,
    "obligatorio_si" "text",
    "no_obligatorio_si" "text",
    "maximo" integer,
    "formatos" "text"[],
    "lista_de_opciones" "text",
    "vigencia" boolean DEFAULT false NOT NULL,
    "orden" integer DEFAULT 100 NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "formulario_campos_etiqueta_completa" CHECK ("interno"."texto_en_los_tres_idiomas"("etiqueta")),
    CONSTRAINT "formulario_campos_formatos_solo_en_archivo" CHECK (((("tipo" = 'archivo'::"text") AND ("formatos" IS NOT NULL) AND ("array_length"("formatos", 1) > 0)) OR (("tipo" <> 'archivo'::"text") AND ("formatos" IS NULL)))),
    CONSTRAINT "formulario_campos_lista_de_opciones_solo_en_lista" CHECK (((("tipo" = ANY (ARRAY['lista'::"text", 'lista_multiple'::"text"])) AND ("lista_de_opciones" IS NOT NULL)) OR (("tipo" <> ALL (ARRAY['lista'::"text", 'lista_multiple'::"text"])) AND ("lista_de_opciones" IS NULL)))),
    CONSTRAINT "formulario_campos_maximo_positivo" CHECK ((("maximo" IS NULL) OR ("maximo" > 0))),
    CONSTRAINT "formulario_campos_tipo_check" CHECK (("tipo" = ANY (ARRAY['texto'::"text", 'texto_largo'::"text", 'fecha'::"text", 'anio'::"text", 'mes_anio'::"text", 'casilla'::"text", 'archivo'::"text", 'telefono'::"text", 'lista'::"text", 'lista_multiple'::"text"]))),
    CONSTRAINT "formulario_campos_una_sola_condicion" CHECK ((("obligatorio_si" IS NULL) OR ("no_obligatorio_si" IS NULL)))
);


ALTER TABLE "public"."formulario_campos" OWNER TO "postgres";


COMMENT ON TABLE "public"."formulario_campos" IS 'Los casilleros de cada sección. No hay columna de ayuda: un casillero lleva su etiqueta y nada más.';



COMMENT ON COLUMN "public"."formulario_campos"."formatos" IS 'Qué formatos de archivo acepta el casillero. Lo que acepta el depósito manda igual: esto no lo amplía.';



COMMENT ON COLUMN "public"."formulario_campos"."lista_de_opciones" IS 'De que lista de opciones elige este casillero. Es la clave de una fila de listas_de_opciones; las opciones salen de la base y nunca escritas adentro de la pantalla.';



CREATE TABLE IF NOT EXISTS "public"."formulario_secciones" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "formulario_id" "uuid" NOT NULL,
    "prestadora_id" "uuid",
