    "obligatoria_cuando" "text",
    "orden" integer DEFAULT 100 NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "formulario_secciones_titulo_completo" CHECK ("interno"."texto_en_los_tres_idiomas"("titulo")),
    CONSTRAINT "formulario_secciones_tope_solo_si_repite" CHECK ((("maximo_repeticiones" IS NULL) OR (("repetible" = true) AND ("maximo_repeticiones" > 0))))
);


ALTER TABLE "public"."formulario_secciones" OWNER TO "postgres";


COMMENT ON COLUMN "public"."formulario_secciones"."obligatoria_cuando" IS 'Vacío: la sección es obligatoria desde que se abre el formulario. Con dato: es la condición que la vuelve obligatoria, escrita como la lee el motor.';



