    CONSTRAINT "incidentes_relevo_resuelto_por_tipo_check" CHECK (("resuelto_por_tipo" = ANY (ARRAY['suplente'::"text", 'franquero'::"text", 'emergencia'::"text", 'titular'::"text", 'coordinador'::"text", 'familiar'::"text", 'paciente_solo'::"text", 'nadie'::"text"])))
);


