CREATE TABLE IF NOT EXISTS "public"."listas_de_opciones" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid",
    "clave" "text" NOT NULL,
    "i18n" "jsonb" NOT NULL,
    "admite_opciones_propias" boolean DEFAULT false NOT NULL,
    "orden" smallint DEFAULT 0 NOT NULL,
    "activa" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "el_titulo_de_la_lista_esta_en_los_idiomas_que_le_tocan" CHECK (
CASE
    WHEN ("prestadora_id" IS NOT NULL) THEN "interno"."i18n_minimo"("i18n")
    ELSE "interno"."i18n_completo"("i18n")
END),
    CONSTRAINT "la_clave_de_la_lista_no_esta_vacia" CHECK (("length"("btrim"("clave")) > 0))
);


ALTER TABLE "public"."listas_de_opciones" OWNER TO "postgres";


COMMENT ON TABLE "public"."listas_de_opciones" IS 'Las listas de opciones del producto y las que agrega cada Prestadora. Una lista nueva es una fila, no una migracion.';



COMMENT ON COLUMN "public"."listas_de_opciones"."prestadora_id" IS 'Nulo: la lista que trae el producto, igual para todas. Con valor: la que armo esa Prestadora.';



COMMENT ON COLUMN "public"."listas_de_opciones"."clave" IS 'Nombre guardado. Lo cita la pantalla que pide la lista, asi que no se renombra.';



COMMENT ON COLUMN "public"."listas_de_opciones"."admite_opciones_propias" IS 'Si esta lista admite opciones propias de una Prestadora. Falsa cuando lo que guarda se compara entre Organizaciones o contra la ley.';



CREATE TABLE IF NOT EXISTS "public"."llaves_de_dispositivo" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "usuario_id" "uuid" NOT NULL,
    "rol" "text" NOT NULL,
    "credencial_id" "text" NOT NULL,
    "clave_publica" "text" NOT NULL,
    "contador" bigint DEFAULT 0 NOT NULL,
    "transportes" "text"[],
    "creada_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ultimo_uso_en" timestamp with time zone,
    "revocada_en" timestamp with time zone,
    CONSTRAINT "llaves_de_dispositivo_rol_check" CHECK (("rol" = ANY (ARRAY['asistente'::"text", 'cliente'::"text"])))
);


ALTER TABLE "public"."llaves_de_dispositivo" OWNER TO "postgres";


COMMENT ON TABLE "public"."llaves_de_dispositivo" IS 'Llaves que cada persona guarda en su propio telefono para entrar sin escribir la contrasena. Se guarda la mitad publica de la llave; la privada nunca sale del aparato y ningun dato biometrico entra aca.';



COMMENT ON COLUMN "public"."llaves_de_dispositivo"."rol" IS 'En cual de las dos aplicaciones nacio la llave. Una llave del Asistente no sirve para entrar a la del Cliente: son dos aplicaciones con permisos distintos.';



COMMENT ON COLUMN "public"."llaves_de_dispositivo"."credencial_id" IS 'Como el telefono nombra a esta llave. Unico en todo el producto, porque asi llega la firma cuando la pantalla de ingreso todavia no sabe quien esta entrando.';



COMMENT ON COLUMN "public"."llaves_de_dispositivo"."contador" IS 'Cuantas veces el aparato dice haber usado esta llave. Si baja, hay dos copias de la misma llave dando vueltas. Muchos telefonos no llevan cuenta y lo dejan siempre en cero.';



COMMENT ON COLUMN "public"."llaves_de_dispositivo"."revocada_en" IS 'Cuando se dio de baja. La fila no se borra: deja constancia de que esa llave existio.';



CREATE TABLE IF NOT EXISTS "public"."lugares" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
