    "pais" "text" NOT NULL,
    "provincia" "text",
    "municipio" "text",
    "id_oficial" "text",
    "fuente" "text" DEFAULT 'propio'::"text" NOT NULL,
    "parte_de" "uuid",
    "lat" double precision,
    "lng" double precision,
    "activo" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "localidad_censal" "text",
    CONSTRAINT "lugares_el_oficial_trae_su_identificador" CHECK ((("fuente" <> 'oficial'::"text") OR ("id_oficial" IS NOT NULL))),
    CONSTRAINT "lugares_fuente_conocida" CHECK (("fuente" = ANY (ARRAY['oficial'::"text", 'propio'::"text"]))),
    CONSTRAINT "lugares_no_se_contiene_a_si_mismo" CHECK ((("parte_de" IS NULL) OR ("parte_de" <> "id")))
);


ALTER TABLE "public"."lugares" OWNER TO "postgres";


COMMENT ON TABLE "public"."lugares" IS 'Las localidades y los barrios donde trabaja una Prestadora, en una sola lista de un solo nivel. Cada renglon dice si salio del organismo oficial del pais o lo agrego la Prestadora.';



COMMENT ON COLUMN "public"."lugares"."id_oficial" IS 'El identificador del organismo oficial del pais. En blanco cuando el lugar lo agrego la Prestadora.';



COMMENT ON COLUMN "public"."lugares"."fuente" IS 'oficial (nombre e identificador del organismo, no se editan a mano) o propio (los puso la Prestadora).';



COMMENT ON COLUMN "public"."lugares"."parte_de" IS 'El lugar que lo contiene, cuando lo hay: un barrio cuelga de su localidad. Una localidad no cuelga de nada.';



