    "orden" integer DEFAULT 100 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "motivos_resolucion_estado_no_vacio" CHECK (("length"("btrim"("estado")) > 0)),
    CONSTRAINT "motivos_resolucion_tabla_no_vacia" CHECK (("length"("btrim"("tabla")) > 0)),
    CONSTRAINT "motivos_resolucion_tres_idiomas" CHECK ((("length"("btrim"("nombre_es_ar")) > 0) AND ("length"("btrim"("nombre_en")) > 0) AND ("length"("btrim"("nombre_pt_br")) > 0)))
);


ALTER TABLE "public"."motivos_resolucion" OWNER TO "postgres";


COMMENT ON TABLE "public"."motivos_resolucion" IS 'Por que se resolvio algo. Cada Prestadora arma su lista: nace con los motivos que trae el producto y a partir de ahi agrega, apaga y ordena los suyos.';



COMMENT ON COLUMN "public"."motivos_resolucion"."tabla" IS 'Que se resuelve con este motivo. Es el nombre guardado de la tabla cuya fila se resuelve, por ejemplo postulaciones o solicitudes.';



COMMENT ON COLUMN "public"."motivos_resolucion"."estado" IS 'En que estado queda lo resuelto al elegir este motivo. Lo dice el motivo, no quien llama.';



COMMENT ON COLUMN "public"."motivos_resolucion"."nombre_es_ar" IS 'El motivo escrito en castellano rioplatense. Se muestra tal cual.';



COMMENT ON COLUMN "public"."motivos_resolucion"."nombre_en" IS 'El motivo escrito en ingles. Se muestra tal cual.';



COMMENT ON COLUMN "public"."motivos_resolucion"."nombre_pt_br" IS 'El motivo escrito en portugues de Brasil. Se muestra tal cual.';



COMMENT ON COLUMN "public"."motivos_resolucion"."pide_detalle" IS 'Elegir este motivo obliga a escribir ademas que paso. La base lo exige, no la pantalla.';



