CREATE TABLE IF NOT EXISTS "public"."personas" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "clase" "text" NOT NULL,
    "nombre" "text" NOT NULL,
    "apellido" "text",
    "documento_tipo" "text" NOT NULL,
    "documento_numero" "text" NOT NULL,
    "calle" "text",
    "numero" "text",
    "piso" "text",
    "unidad" "text",
    "lugar_id" "uuid",
    "email" "text",
    "notas" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "nombre_visible" "text" GENERATED ALWAYS AS (
CASE
    WHEN ("clase" = 'juridica'::"text") THEN "nombre"
    WHEN (("apellido" IS NULL) OR ("btrim"("apellido") = ''::"text")) THEN "nombre"
    ELSE (("apellido" || ', '::"text") || "nombre")
END) STORED,
    "documento_pais" "text",
    "fecha_nacimiento" "date",
    "lat" double precision,
    "lng" double precision,
    "codigo_postal" "text",
    "dni" "text",
    "genero" "text",
    CONSTRAINT "personas_clase_conocida" CHECK (("clase" = ANY (ARRAY['fisica'::"text", 'juridica'::"text"]))),
    CONSTRAINT "personas_el_nombre_no_va_vacio" CHECK (("btrim"("nombre") <> ''::"text")),
    CONSTRAINT "personas_la_fisica_lleva_apellido" CHECK ((("clase" <> 'fisica'::"text") OR (("apellido" IS NOT NULL) AND ("btrim"("apellido") <> ''::"text")))),
    CONSTRAINT "personas_la_juridica_no_lleva_apellido" CHECK ((("clase" <> 'juridica'::"text") OR ("apellido" IS NULL))),
    CONSTRAINT "personas_la_juridica_no_nace" CHECK ((("clase" = 'fisica'::"text") OR ("fecha_nacimiento" IS NULL))),
    CONSTRAINT "personas_la_ubicacion_va_entera" CHECK ((("lat" IS NULL) = ("lng" IS NULL)))
);


ALTER TABLE "public"."personas" OWNER TO "postgres";


COMMENT ON TABLE "public"."personas" IS 'El Padron de la Prestadora: un Legajo por Persona, fisica o juridica. Guarda quien es y nada mas; los roles viven donde ocurren y citan el Legajo. No se borra nunca.';



COMMENT ON COLUMN "public"."personas"."clase" IS 'física (una persona) o jurídica (una obra social, una prepaga, una empresa). Las dos cumplen los mismos roles.';



COMMENT ON COLUMN "public"."personas"."nombre" IS 'El nombre de pila de la persona fisica, o la razon social entera de la juridica.';



COMMENT ON COLUMN "public"."personas"."nombre_visible" IS 'Cómo se nombra este Legajo en pantalla. La calcula la base para que todas las pantallas digan lo mismo: la persona jurídica por su razón social, la física por apellido y nombre.';



