CREATE TABLE IF NOT EXISTS "public"."remuneraciones_asistente" (
    "asistente_id" "uuid" NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "valor_hora" numeric(12,2),
    "sueldo_basico" numeric(12,2),
    "categoria_cct" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "moneda" "public"."moneda_iso" NOT NULL,
    "unidad_medicion" "text" DEFAULT 'hora'::"text" NOT NULL,
    "valor_guardia" numeric(12,2),
    "valor_semana" numeric(12,2),
    "valor_hora_extra" numeric(12,2),
    "frecuencia_pago" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "remuneraciones_asistente_frecuencia_es_objeto" CHECK (("jsonb_typeof"("frecuencia_pago") = 'object'::"text")),
    CONSTRAINT "remuneraciones_asistente_unidad_conocida" CHECK (("unidad_medicion" = ANY (ARRAY['hora'::"text", 'guardia'::"text", 'semana'::"text", 'mes'::"text"]))),
    CONSTRAINT "remuneraciones_asistente_valores_no_negativos" CHECK (((COALESCE("valor_hora", (0)::numeric) >= (0)::numeric) AND (COALESCE("sueldo_basico", (0)::numeric) >= (0)::numeric) AND (COALESCE("valor_guardia", (0)::numeric) >= (0)::numeric) AND (COALESCE("valor_semana", (0)::numeric) >= (0)::numeric) AND (COALESCE("valor_hora_extra", (0)::numeric) >= (0)::numeric)))
);


ALTER TABLE "public"."remuneraciones_asistente" OWNER TO "postgres";


COMMENT ON TABLE "public"."remuneraciones_asistente" IS 'Lo que cobra cada Asistente. Vive separado de `asistentes` porque las reglas de acceso de la base filtran filas, no columnas: solo en una tabla propia se puede exigir el permiso `ver_pagos_asistente` para leerlo.';



COMMENT ON COLUMN "public"."remuneraciones_asistente"."unidad_medicion" IS 'Con que se mide el trabajo de esta persona: hora, guardia, semana o mes. No es cada cuanto se le paga, que es otra cosa y se arregla aparte.';



COMMENT ON COLUMN "public"."remuneraciones_asistente"."valor_hora_extra" IS 'Cuanto se le paga la hora de mas. Puede ser igual o distinto al valor hora normal. Vacio quiere decir que no esta cargado: la liquidacion avisa y no estima.';



COMMENT ON COLUMN "public"."remuneraciones_asistente"."frecuencia_pago" IS 'Cada cuánto cobra esta persona. Sólo lo corrido respecto de lo de la Prestadora; vacío es lo de ella.';



