    "tokens_salida" integer NOT NULL,
    "creado_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "uso_ia_modulo_check" CHECK (("modulo" = ANY (ARRAY['alertas'::"text", 'reporte'::"text", 'importacion'::"text", 'importacion_viabilidad'::"text", 'importacion_localidades'::"text", 'importacion_generos'::"text", 'whatsapp'::"text", 'plantillas_whatsapp'::"text", 'motivo_aviso_previo'::"text", 'asignacion'::"text"])))
);


ALTER TABLE "public"."uso_ia" OWNER TO "postgres";


COMMENT ON COLUMN "public"."uso_ia"."modulo" IS 'Qué parte del producto gastó en IA. Lista cerrada: sumar un valor acá es la forma de que un módulo nuevo pueda anotar su costo.';



