-- Las cuentas automáticas: con qué entra el backend a la base, una por Prestadora y por trabajo,
-- y la alarma que las corta cuando entran demasiadas veces. El pase de cada una lo arma
-- `interno.armar_el_pase`, que Supabase llama cada vez que entrega uno.
CREATE TABLE interno.cuentas_automaticas (
  id            uuid PRIMARY KEY REFERENCES auth.users (id) ON DELETE CASCADE,
  prestadora_id uuid REFERENCES public.prestadoras (id) ON DELETE CASCADE,
  rol           text NOT NULL CHECK (rol IN ('trabajo_sin_persona', 'copia_de_respaldo')),
  trabajo       text CHECK (trabajo IN ('importación de planillas')),
  CHECK (rol = 'trabajo_sin_persona' OR prestadora_id IS NOT NULL),
  CHECK (trabajo IS NULL OR (rol = 'trabajo_sin_persona' AND prestadora_id IS NOT NULL))
);

CREATE UNIQUE INDEX cuentas_automaticas_una_por_prestadora_y_rol
  ON interno.cuentas_automaticas (coalesce(prestadora_id, '00000000-0000-0000-0000-000000000000'::uuid), rol, coalesce(trabajo, ''));

CREATE TABLE interno.alarma_de_las_cuentas_automaticas (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  entradas_maximas integer NOT NULL CHECK (entradas_maximas > 0),
  ventana          interval NOT NULL CHECK (ventana > interval '0')
);
CREATE UNIQUE INDEX alarma_de_las_cuentas_automaticas_una_sola ON interno.alarma_de_las_cuentas_automaticas ((true));

CREATE TABLE interno.entradas_de_cuentas_automaticas (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  cuenta_id     uuid NOT NULL REFERENCES interno.cuentas_automaticas (id) ON DELETE CASCADE,
  prestadora_id uuid REFERENCES public.prestadoras (id) ON DELETE CASCADE,
  creada_en     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX entradas_de_cuentas_automaticas_por_cuenta ON interno.entradas_de_cuentas_automaticas (cuenta_id, creada_en);

CREATE TABLE interno.alarmas_de_cuentas_automaticas (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  cuenta_id     uuid NOT NULL,
  prestadora_id uuid REFERENCES public.prestadoras (id) ON DELETE CASCADE,
  cuenta        text NOT NULL,
  entradas      integer NOT NULL,
  ventana       interval NOT NULL,
  sono_en       timestamptz NOT NULL DEFAULT now(),
  avisada_en    timestamptz
);

ALTER TABLE interno.cuentas_automaticas ENABLE ROW LEVEL SECURITY;
ALTER TABLE interno.alarma_de_las_cuentas_automaticas ENABLE ROW LEVEL SECURITY;
ALTER TABLE interno.entradas_de_cuentas_automaticas ENABLE ROW LEVEL SECURITY;
ALTER TABLE interno.alarmas_de_cuentas_automaticas ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON interno.cuentas_automaticas FROM PUBLIC, anon, authenticated;
REVOKE ALL ON interno.alarma_de_las_cuentas_automaticas FROM PUBLIC, anon, authenticated;
REVOKE ALL ON interno.entradas_de_cuentas_automaticas FROM PUBLIC, anon, authenticated;
REVOKE ALL ON interno.alarmas_de_cuentas_automaticas FROM PUBLIC, anon, authenticated;

GRANT SELECT ON interno.cuentas_automaticas TO supabase_auth_admin;
CREATE POLICY la_lee_quien_arma_el_pase ON interno.cuentas_automaticas
  FOR SELECT TO supabase_auth_admin USING (true);
GRANT SELECT ON interno.alarma_de_las_cuentas_automaticas TO supabase_auth_admin;
CREATE POLICY la_lee_quien_arma_el_pase ON interno.alarma_de_las_cuentas_automaticas
  FOR SELECT TO supabase_auth_admin USING (true);
GRANT SELECT, INSERT, DELETE ON interno.entradas_de_cuentas_automaticas TO supabase_auth_admin;
CREATE POLICY las_cuenta_quien_arma_el_pase ON interno.entradas_de_cuentas_automaticas
  FOR ALL TO supabase_auth_admin USING (true) WITH CHECK (true);
GRANT INSERT ON interno.alarmas_de_cuentas_automaticas TO supabase_auth_admin;
CREATE POLICY la_anota_quien_arma_el_pase ON interno.alarmas_de_cuentas_automaticas
  FOR INSERT TO supabase_auth_admin WITH CHECK (true);

CREATE FUNCTION interno.armar_el_pase(event jsonb) RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
AS $$
DECLARE
  v_cuenta   interno.cuentas_automaticas;
  v_alarma   interno.alarma_de_las_cuentas_automaticas;
  v_entradas integer;
  v_datos    jsonb;
BEGIN
  SELECT * INTO v_cuenta FROM interno.cuentas_automaticas
   WHERE id = (event ->> 'user_id')::uuid;

  -- Una persona: el pase sale como siempre.
  IF NOT FOUND THEN
    RETURN event;
  END IF;

  -- Sólo se cuentan las entradas con contraseña: renovar el pase no es entrar.
  IF event ->> 'authentication_method' = 'password' THEN
    SELECT * INTO v_alarma FROM interno.alarma_de_las_cuentas_automaticas;
    -- Sin la regla no se sabe cuántas son demasiadas: no entra nadie.
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Falta la regla de la alarma de las cuentas automáticas';
    END IF;

    DELETE FROM interno.entradas_de_cuentas_automaticas
     WHERE cuenta_id = v_cuenta.id AND creada_en < now() - v_alarma.ventana;
    INSERT INTO interno.entradas_de_cuentas_automaticas (cuenta_id, prestadora_id)
      VALUES (v_cuenta.id, v_cuenta.prestadora_id);
    SELECT count(*) INTO v_entradas FROM interno.entradas_de_cuentas_automaticas
     WHERE cuenta_id = v_cuenta.id;

    IF v_entradas > v_alarma.entradas_maximas THEN
      -- Desactivada: Supabase no la deja entrar ni renovar. Se reactiva al cambiarle la contraseña.
      UPDATE auth.users SET banned_until = now() + interval '100 years' WHERE id = v_cuenta.id;
      INSERT INTO interno.alarmas_de_cuentas_automaticas (cuenta_id, prestadora_id, cuenta, entradas, ventana)
        SELECT v_cuenta.id, v_cuenta.prestadora_id, split_part(u.email, '@', 1), v_entradas, v_alarma.ventana
          FROM auth.users u WHERE u.id = v_cuenta.id;
      -- El pase de esta entrada sale igual, porque si no Supabase deshace todo lo anterior. Pero
      -- sale sin rol de trabajo y sin Prestadora: no abre nada.
      RETURN jsonb_build_object('claims',
        ((event -> 'claims') - 'prestadora_id' - 'trabajo') || jsonb_build_object('role', 'anon'));
    END IF;
  END IF;

  v_datos := (event -> 'claims') || jsonb_build_object('role', v_cuenta.rol);
  IF v_cuenta.prestadora_id IS NOT NULL THEN
    v_datos := v_datos || jsonb_build_object('prestadora_id', v_cuenta.prestadora_id);
  END IF;
  IF v_cuenta.trabajo IS NOT NULL THEN
    v_datos := v_datos || jsonb_build_object('trabajo', v_cuenta.trabajo);
  ELSE
    v_datos := v_datos - 'trabajo';
  END IF;
  RETURN jsonb_build_object('claims', v_datos);
END;
$$;

REVOKE EXECUTE ON FUNCTION interno.armar_el_pase(jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION interno.armar_el_pase(jsonb) TO supabase_auth_admin;

CREATE FUNCTION public.alarmas_de_cuentas_automaticas_a_avisar()
  RETURNS TABLE (id uuid, cuenta text, entradas integer, minutos integer, sono_en timestamptz)
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path TO ''
AS $$
  SELECT a.id, a.cuenta, a.entradas, (extract(epoch FROM a.ventana) / 60)::integer, a.sono_en
    FROM interno.alarmas_de_cuentas_automaticas a
   WHERE a.avisada_en IS NULL
     AND auth.jwt() ->> 'role' = 'trabajo_sin_persona'
     AND auth.jwt() ->> 'prestadora_id' IS NULL
   ORDER BY a.sono_en
$$;

CREATE FUNCTION public.alarma_de_cuenta_automatica_avisada(p_alarma uuid) RETURNS void
  LANGUAGE sql SECURITY DEFINER
  SET search_path TO ''
AS $$
  UPDATE interno.alarmas_de_cuentas_automaticas SET avisada_en = now()
   WHERE id = p_alarma AND avisada_en IS NULL
     AND auth.jwt() ->> 'role' = 'trabajo_sin_persona'
     AND auth.jwt() ->> 'prestadora_id' IS NULL
$$;

REVOKE EXECUTE ON FUNCTION public.alarmas_de_cuentas_automaticas_a_avisar() FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.alarma_de_cuenta_automatica_avisada(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.alarmas_de_cuentas_automaticas_a_avisar() TO trabajo_sin_persona;
GRANT EXECUTE ON FUNCTION public.alarma_de_cuenta_automatica_avisada(uuid) TO trabajo_sin_persona;
CREATE FUNCTION interno.borrar_la_cuenta_automatica() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER
  SET search_path TO ''
AS $$
BEGIN
  DELETE FROM auth.users WHERE id = OLD.id;
  RETURN NULL;
END;
$$;

REVOKE EXECUTE ON FUNCTION interno.borrar_la_cuenta_automatica() FROM PUBLIC, anon, authenticated;

CREATE TRIGGER borrar_la_cuenta_automatica
  AFTER DELETE ON interno.cuentas_automaticas
  FOR EACH ROW EXECUTE FUNCTION interno.borrar_la_cuenta_automatica();



-- Toda tabla con datos de una Prestadora dice de cuál es. Las que lo sabían sólo por su fila
-- madre lo dicen con una clave foránea doble —madre y Prestadora juntas—, así que no puede quedar
-- distinta de la de la madre.
-- Las madres ofrecen el par para que las hijas lo citen.
CREATE UNIQUE INDEX clientes_id_y_prestadora ON public.clientes (id, prestadora_id);
CREATE UNIQUE INDEX usuarios_id_y_prestadora ON public.usuarios (id, prestadora_id);
CREATE UNIQUE INDEX asistentes_id_y_prestadora ON public.asistentes (id, prestadora_id);
CREATE UNIQUE INDEX liquidaciones_asistente_id_y_prestadora ON public.liquidaciones_asistente (id, prestadora_id);
CREATE UNIQUE INDEX accesos_intermediacion_id_y_prestadora ON public.accesos_intermediacion (id, prestadora_id);

-- liquidaciones_asistente_items ← liquidaciones_asistente
ALTER TABLE public.liquidaciones_asistente_items
  ADD COLUMN prestadora_id uuid NOT NULL DEFAULT interno.prestadora_actual(),
  ADD CONSTRAINT liquidaciones_asistente_items_prestadora_de_la_liquidacion
    FOREIGN KEY (liquidacion_id, prestadora_id) REFERENCES public.liquidaciones_asistente (id, prestadora_id) ON DELETE CASCADE;
CREATE INDEX liquidaciones_asistente_items_prestadora ON public.liquidaciones_asistente_items (prestadora_id);

-- permisos_personas_autorizadas ← clientes
ALTER TABLE public.permisos_personas_autorizadas
  ADD COLUMN prestadora_id uuid NOT NULL DEFAULT interno.prestadora_actual(),
  ADD CONSTRAINT permisos_personas_autorizadas_de_la_prestadora_del_cliente
    FOREIGN KEY (cliente_id, prestadora_id) REFERENCES public.clientes (id, prestadora_id) ON DELETE CASCADE;
CREATE INDEX permisos_personas_autorizadas_prestadora ON public.permisos_personas_autorizadas (prestadora_id);

-- personas_autorizadas ← clientes
ALTER TABLE public.personas_autorizadas
  ADD COLUMN prestadora_id uuid NOT NULL DEFAULT interno.prestadora_actual(),
  ADD CONSTRAINT personas_autorizadas_de_la_prestadora_del_cliente
    FOREIGN KEY (cliente_id, prestadora_id) REFERENCES public.clientes (id, prestadora_id) ON DELETE CASCADE;
CREATE INDEX personas_autorizadas_prestadora ON public.personas_autorizadas (prestadora_id);

-- qr_cobro_efectivo ← accesos_intermediacion
ALTER TABLE public.qr_cobro_efectivo
  ADD COLUMN prestadora_id uuid NOT NULL DEFAULT interno.prestadora_actual(),
  ADD CONSTRAINT qr_cobro_efectivo_de_la_prestadora_del_acceso
    FOREIGN KEY (acceso_id, prestadora_id) REFERENCES public.accesos_intermediacion (id, prestadora_id) ON DELETE CASCADE;
CREATE INDEX qr_cobro_efectivo_prestadora ON public.qr_cobro_efectivo (prestadora_id);

-- tokens_activacion_cuenta ← usuarios
ALTER TABLE public.tokens_activacion_cuenta
  ADD COLUMN prestadora_id uuid NOT NULL DEFAULT interno.prestadora_actual(),
  ADD CONSTRAINT tokens_activacion_cuenta_de_la_prestadora_del_usuario
    FOREIGN KEY (usuario_id, prestadora_id) REFERENCES public.usuarios (id, prestadora_id) ON DELETE CASCADE;
CREATE INDEX tokens_activacion_cuenta_prestadora ON public.tokens_activacion_cuenta (prestadora_id);

-- tokens_recuperacion_clave ← usuarios
ALTER TABLE public.tokens_recuperacion_clave
  ADD COLUMN prestadora_id uuid NOT NULL DEFAULT interno.prestadora_actual(),
  ADD CONSTRAINT tokens_recuperacion_clave_de_la_prestadora_del_usuario
    FOREIGN KEY (usuario_id, prestadora_id) REFERENCES public.usuarios (id, prestadora_id) ON DELETE CASCADE;
CREATE INDEX tokens_recuperacion_clave_prestadora ON public.tokens_recuperacion_clave (prestadora_id);

-- verificaciones_asistente ← asistentes
ALTER TABLE public.verificaciones_asistente
  ADD COLUMN prestadora_id uuid NOT NULL DEFAULT interno.prestadora_actual(),
  ADD CONSTRAINT verificaciones_asistente_de_la_prestadora_del_asistente
    FOREIGN KEY (asistente_id, prestadora_id) REFERENCES public.asistentes (id, prestadora_id) ON DELETE CASCADE;
CREATE INDEX verificaciones_asistente_prestadora ON public.verificaciones_asistente (prestadora_id);


-- La copia de respaldo de los datos, de a una Prestadora por vez: lo único que puede llamar la
-- cuenta `copia_de_respaldo`. El filtro lo ponen las funciones, y es la Prestadora del pase.
CREATE FUNCTION public.tablas_del_respaldo() RETURNS SETOF text
  LANGUAGE plpgsql STABLE SECURITY DEFINER
  SET search_path TO ''
AS $$
BEGIN
  IF auth.jwt() ->> 'role' IS DISTINCT FROM 'copia_de_respaldo' OR interno.prestadora_actual() IS NULL THEN
    RAISE EXCEPTION 'Sin permiso para la copia de respaldo' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
    SELECT 'public.prestadoras'
    UNION ALL
    (SELECT 'public.' || c.relname::text
       FROM pg_catalog.pg_class c
       JOIN pg_catalog.pg_attribute a
         ON a.attrelid = c.oid AND a.attname = 'prestadora_id' AND NOT a.attisdropped
      WHERE c.relnamespace = 'public'::regnamespace
        AND c.relkind IN ('r', 'p') AND NOT c.relispartition
      ORDER BY c.relname)
    UNION ALL
    SELECT unnest(ARRAY['auth.users', 'auth.identities', 'auth.mfa_factors']);
END;
$$;

CREATE FUNCTION public.filas_del_respaldo(p_tabla text, p_desde integer, p_cantidad integer) RETURNS jsonb
  LANGUAGE plpgsql STABLE SECURITY DEFINER
  SET search_path TO ''
AS $$
DECLARE
  v_prestadora uuid := interno.prestadora_actual();
  v_nombre     text[];
  v_filtro     text;
  v_orden      text;
  v_filas      jsonb;
BEGIN
  IF auth.jwt() ->> 'role' IS DISTINCT FROM 'copia_de_respaldo' OR v_prestadora IS NULL THEN
    RAISE EXCEPTION 'Sin permiso para la copia de respaldo' USING ERRCODE = '42501';
  END IF;
  IF p_tabla IS NULL OR p_tabla NOT IN (SELECT public.tablas_del_respaldo()) THEN
    RAISE EXCEPTION 'Tabla fuera de la copia de respaldo' USING ERRCODE = '22023';
  END IF;
  IF p_desde IS NULL OR p_desde < 0 OR p_cantidad IS NULL OR p_cantidad NOT BETWEEN 1 AND 5000 THEN
    RAISE EXCEPTION 'Tramo de la copia de respaldo mal pedido' USING ERRCODE = '22023';
  END IF;

  v_nombre := pg_catalog.parse_ident(p_tabla);

  v_filtro := CASE p_tabla
    WHEN 'public.prestadoras'  THEN 't.id = $1'
    WHEN 'auth.users'          THEN 't.id IN (SELECT u.id FROM public.usuarios u WHERE u.prestadora_id = $1)'
    WHEN 'auth.identities'     THEN 't.user_id IN (SELECT u.id FROM public.usuarios u WHERE u.prestadora_id = $1)'
    WHEN 'auth.mfa_factors'    THEN 't.user_id IN (SELECT u.id FROM public.usuarios u WHERE u.prestadora_id = $1)'
    ELSE 't.prestadora_id = $1'
  END;

  -- Siempre el mismo orden, el de la clave primaria, para que los tramos no se pisen.
  SELECT string_agg(format('t.%I', a.attname), ', ' ORDER BY array_position(i.indkey::int2[], a.attnum))
    INTO v_orden
    FROM pg_catalog.pg_index i
    JOIN pg_catalog.pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = ANY (i.indkey)
   WHERE i.indrelid = format('%I.%I', v_nombre[1], v_nombre[2])::regclass AND i.indisprimary;
  IF v_orden IS NULL THEN
    RAISE EXCEPTION 'La tabla % no tiene clave primaria', p_tabla;
  END IF;

  EXECUTE format(
    'SELECT coalesce(jsonb_agg(x.fila), ''[]''::jsonb) FROM (SELECT to_jsonb(t) AS fila FROM %I.%I t WHERE %s ORDER BY %s OFFSET $2 LIMIT $3) x',
    v_nombre[1], v_nombre[2], v_filtro, v_orden)
    INTO v_filas
    USING v_prestadora, p_desde, p_cantidad;

  RETURN v_filas;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.tablas_del_respaldo() FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.filas_del_respaldo(text, integer, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.tablas_del_respaldo() TO copia_de_respaldo;
GRANT EXECUTE ON FUNCTION public.filas_del_respaldo(text, integer, integer) TO copia_de_respaldo;
